export function debounce<T extends (...args: any[]) => any>(
  func: T,
  wait: number
): (...args: Parameters<T>) => void {
  let timeout: NodeJS.Timeout | null = null;
  
  return (...args: Parameters<T>) => {
    if (timeout) {
      clearTimeout(timeout);
    }
    
    timeout = setTimeout(() => {
      func(...args);
    }, wait);
  };
}

export function throttle<T extends (...args: any[]) => any>(
  func: T,
  limit: number
): (...args: Parameters<T>) => void {
  let inThrottle: boolean = false;
  
  return (...args: Parameters<T>) => {
    if (!inThrottle) {
      func(...args);
      inThrottle = true;
      setTimeout(() => inThrottle = false, limit);
    }
  };
}

// bunching function
// bunching function is a function that calls a function after a certain number of packets
// if wait for next packet is more than time limit, call function immediately
export function bunch<T extends (...args: any[]) => any>(
  func: T,
  nPackets: number,
  timeLimit: number = 1000
): (...args: Parameters<T>) => void {
  let count = 0;
  let lastFunctionCallTime = Date.now();
  let timeoutId: NodeJS.Timeout | null = null;
  let lastArgs: Parameters<T>;
  
  const executeFunction = (args: Parameters<T>) => {
    func(...args);
    count = 0;
    lastFunctionCallTime = Date.now();
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
  };
  
  return (...args: Parameters<T>) => {
    count++;
    lastArgs = args;
    if (timeoutId) {
      clearTimeout(timeoutId);
    }
    
    // Если достигли нужного количества пакетов, вызываем функцию
    if (count >= nPackets) {
      executeFunction(args);
      return;
    }
    
    // Устанавливаем таймер для вызова функции через timeLimit
    timeoutId = setTimeout(() => {
      if (count > 0) {
        executeFunction(lastArgs);
      }
    }, timeLimit);

  };
}