import React, { useState, useEffect } from 'react';
import classNames from 'classnames';
import CountUp from '../CountUp';
import { WarpTravelState } from '../../types';
import styles from './index.module.scss';

interface WarpResourcesPanelProps {
  warpTravel: WarpTravelState;
  warpCooldownProgress: number;
}

export const WarpResourcesPanel: React.FC<WarpResourcesPanelProps> = ({
  warpTravel,
  warpCooldownProgress
}) => {
  const [isVisible, setIsVisible] = useState(false);
  const [shouldRender, setShouldRender] = useState(false);

  // Determine if panel should be visible
  const shouldBeVisible = 
    warpTravel.isUnlocked && 
    ((warpTravel.warpResources || 0) > 0 || 
     warpTravel.warpCooldownEndTime > Date.now() || 
     warpTravel.isActive);

  useEffect(() => {
    if (shouldBeVisible) {
      // Show panel
      setShouldRender(true);
      // Small delay to ensure DOM is ready for animation
      const showTimer = setTimeout(() => setIsVisible(true), 10);
      return () => clearTimeout(showTimer);
    } else {
      // Hide panel
      setIsVisible(false);
      // Remove from DOM after animation completes
      const hideTimer = setTimeout(() => setShouldRender(false), 300);
      return () => clearTimeout(hideTimer);
    }
  }, [shouldBeVisible]);

  // Don't render if not needed
  if (!shouldRender) {
    return null;
  }

  return (
    <div className={classNames(
      styles.warpResourcesPanel,
      { [styles.visible]: isVisible }
    )}>
      <div className={styles.warpResourcesTitle}>🔥 Варп-Ресурсы</div>
      <div className={styles.warpResourcesAmount}>
        <CountUp 
          value={warpTravel.warpResources || 0} 
          suffix=" ₿" 
          duration={500} 
          showColors={false}
        />
      </div>

      {warpTravel.warpCooldownEndTime > 0 && (
        <div className={styles.warpCooldownBar}>
          <div 
            className={styles.warpCooldownFill}
            style={{ width: `${warpCooldownProgress * 100}%` }}
            data-testid="warp-cooldown-fill"
          />
        </div>
      )}
    </div>
  );
};