import React from "react";

interface AnimatedSpriteProps {
  id: string;
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  clipWidth?: number;
  clipHeight?: number;
  duration?: string;
  imagePath?: string;
  standalone?: boolean;
  className?: string;
  style?: React.CSSProperties;
}

export const AnimatedSprite: React.FC<AnimatedSpriteProps> = ({
  id,
  x = 0,
  y = 0,
  width = 32,
  height = 50,
  clipWidth = 15,
  clipHeight = 15,
  duration = "0.16s",
  imagePath = `${process.env.PUBLIC_URL}/assets/sprite-animation.png`,
  standalone = false,
  className = "",
  style = {}
}) => {
  const offsetX = -0.5;
  const offsetY = -2;
  const rightColumnX = -16.35;
  const row1Y = offsetY;
  const row2Y = -16.9;
  const row3Y = -31.5;

  if (standalone) {
    // Для использования в обычном JSX
    return (
      <div 
        id={id}
        className={className}
        style={{
          display: 'inline-block',
          overflow: 'hidden',
          ...style
        }}
      >
        <svg 
          width={clipWidth} 
          height={clipHeight} 
          viewBox={`0 0 16 16`}
          style={{ display: 'block' }}
        >
          <defs>
            <clipPath id={`spriteClip-${id}`}>
              <rect x="0" y="0" width={clipWidth} height={clipHeight} />
            </clipPath>
          </defs>
          
          <g clipPath={`url(#spriteClip-${id})`}>
            <image 
              xlinkHref={imagePath}
              x="0" 
              y="2" 
              width={width} 
              height={height}
            >
              <animateTransform
                attributeName="transform"
                attributeType="XML"
                type="translate"
                values={`${offsetX},${row1Y}; ${rightColumnX},${row1Y}; ${offsetX},${row2Y}; ${rightColumnX},${row2Y}; ${offsetX},${row3Y}; ${rightColumnX},${row3Y}`}
                dur={duration}
                repeatCount="indefinite"
                calcMode="discrete"
              />
            </image>
          </g>
        </svg>
      </div>
    );
  }

  // Для использования внутри SVG
  return (
    <>
      <defs>
        <clipPath id={`spriteClip`}>
          <rect x={x} y={y} width={clipWidth} height={clipHeight} />
        </clipPath>
      </defs>
      
      <g clipPath={`url(#spriteClip)`}>
        <image 
          xlinkHref={imagePath}
          x={x} 
          y={y + 2} 
          width={width} 
          height={height}
        >
          <animateTransform
            attributeName="transform"
            attributeType="XML"
            type="translate"
            values={`${offsetX},${row1Y}; ${rightColumnX},${row1Y}; ${offsetX},${row2Y}; ${rightColumnX},${row2Y}; ${offsetX},${row3Y}; ${rightColumnX},${row3Y}`}
            dur={duration}
            repeatCount="indefinite"
            calcMode="discrete"
          />
        </image>
      </g>
    </>
  );
}; 