import { useTranslation } from 'react-i18next';
import { useCallback } from 'react';

// Хук для удобной работы с переводами
export const useI18n = () => {
  const { t, i18n } = useTranslation();

  // Функция для форматирования чисел с учетом локали
  const formatNumber = useCallback((value: number, decimals: number = 0): string => {
    const locale = i18n.language === 'ru' ? 'ru-RU' : 'en-US';
    return new Intl.NumberFormat(locale, {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals
    }).format(value);
  }, [i18n.language]);

  // Функция для сокращенного отображения больших чисел
  const formatShortNumber = useCallback((value: number): string => {
    const absValue = Math.abs(value);
    
    if (absValue >= 1e12) {
      return `${formatNumber(value / 1e12, 2)} ${t('numbers.trillion')}`;
    } else if (absValue >= 1e9) {
      return `${formatNumber(value / 1e9, 2)} ${t('numbers.billion')}`;
    } else if (absValue >= 1e6) {
      return `${formatNumber(value / 1e6, 2)} ${t('numbers.million')}`;
    } else if (absValue >= 1e3) {
      return `${formatNumber(value / 1e3, 1)} ${t('numbers.thousand')}`;
    }
    
    return formatNumber(value);
  }, [formatNumber, t]);

  // Функция для перевода с множественными формами
  const tPlural = useCallback((key: string, count: number, options?: any): string => {
    return String(t(key, { count, ...options }));
  }, [t]);

  // Функция для форматирования времени
  const formatTime = useCallback((seconds: number): string => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;

    const parts = [];
    if (hours > 0) parts.push(tPlural('time.hour', hours));
    if (minutes > 0) parts.push(tPlural('time.minute', minutes));
    if (secs > 0 || parts.length === 0) parts.push(tPlural('time.second', secs));

    return parts.join(' ');
  }, [tPlural]);

  return {
    t,
    tPlural,
    i18n,
    formatNumber,
    formatShortNumber,
    formatTime,
    currentLanguage: i18n.language,
    changeLanguage: i18n.changeLanguage,
  };
};