import React, { useState, useEffect, useCallback, useRef } from 'react';
import styles from './wormhole.module.scss';
import classNames from 'classnames';
import { useAppDispatch, useAppSelector } from '../../app/hooks';
import { setProjectMultiplier, selectResources, selectTotal, updateResources, selectProjectMultiplier } from '../../app/gameSlice';
import { COMMON } from '../../app/constants';
import { bunch } from '../../utils/debounce';
import { useI18n } from '../../hooks/useI18n';

interface Star {
  id: number;
  angle: number;
  radius: number;
  type: 'safe' | 'dangerous';
  visualType: 1 | 2 | 3; // Строка в спрайтшите
}

type GameState = 'waiting' | 'animating' | 'playing' | 'ending' | 'ended';

export const Wormhole = () => {
  const dispatch = useAppDispatch();
  const resources = useAppSelector(selectResources);
  const total = useAppSelector(selectTotal);
  const currentProjectMultiplier = useAppSelector(selectProjectMultiplier);
  const { t } = useI18n();
  
  const [gameState, setGameState] = useState<GameState>('waiting');
  const [multiplier, setMultiplier] = useState(1);
  const [clickCount, setClickCount] = useState(0);
  const [stars, setStars] = useState<Star[]>([]);
  const [starsVisible, setStarsVisible] = useState(false);
  const [savedMultiplier, setSavedMultiplier] = useState<number | null>(null);
  const [savedMultiplierExpiry, setSavedMultiplierExpiry] = useState<number | null>(null);
  // Новые состояния для отслеживания раундов
  const [currentContribution, setCurrentContribution] = useState(1.0);
  const [lastSentContribution, setLastSentContribution] = useState(1.0);
  
  const starRotationRef = useRef<number | null>(null);
  const rotationAngle = useRef(0);

  const bunchedUpdateMultiplier = useCallback(
    bunch((newContribution: number) => {
      if (newContribution !== lastSentContribution) {
        // Получаем текущий projectMultiplier и извлекаем из него вклад PSI
        // Предполагаем что currentProjectMultiplier = psiContribution * wormholeContribution
        const psiContribution = lastSentContribution > 0 ? currentProjectMultiplier / lastSentContribution : 1.0;
        const combinedMultiplier = psiContribution * newContribution;
        
        dispatch(setProjectMultiplier(Math.max(1.0, combinedMultiplier)));
        setLastSentContribution(newContribution);
      }
    }, 5, 200
  ), [dispatch, lastSentContribution, currentProjectMultiplier]);
  useEffect(() => {
    bunchedUpdateMultiplier(savedMultiplier || 1);
  }, [savedMultiplier, bunchedUpdateMultiplier]);


  // Логика временного множителя
  useEffect(() => {
    if (savedMultiplierExpiry && Date.now() > savedMultiplierExpiry) {
      setSavedMultiplier(null);
      setSavedMultiplierExpiry(null);
    }
  }, [savedMultiplierExpiry]);

  // Генерация звезд для нового раунда
  const generateStars = useCallback((round: number) => {
    const starCount = 5 + Math.floor(round / 2); // Больше звезд с каждым раундом
    const dangerousCount = Math.min(round, starCount - 1); // Количество опасных звезд
    
    const newStars: Star[] = [];
    const angleStep = (Math.PI * 2) / starCount;
    
    // Сначала создаем все звезды как безопасные с равномерным распределением по углам
    for (let i = 0; i < starCount; i++) {
      newStars.push({
        id: i,
        angle: i * angleStep + Math.random() * 0.2 - 0.1, // Небольшой случайный сдвиг
        radius: 40,
        type: 'safe',
        visualType: 1 // Пока все как безопасные
      });
    }
    
    // Случайно выбираем индексы для опасных звезд
    const dangerousIndices = new Set<number>();
    while (dangerousIndices.size < dangerousCount) {
      dangerousIndices.add(Math.floor(Math.random() * starCount));
    }
    
    // Назначаем типы и визуальные варианты
    newStars.forEach((star, index) => {
      const isDangerous = dangerousIndices.has(index);
      star.type = isDangerous ? 'dangerous' : 'safe';
      
      if (isDangerous) {
        if (round === 1) {
          // На первом выборе опасные только 3-й тип
          star.visualType = 3;
        } else if (round <= 4) {
          // На 2-4 выборе опасные 2-й и 3-й тип
          star.visualType = Math.random() > 0.5 ? 2 : 3;
        } else {
          // После 5-го все выглядят как 1-й тип
          star.visualType = 1;
        }
      } else {
        // Безопасные всегда 1-й тип
        star.visualType = 1;
      }
    });
    
    return newStars;
  }, []);

  // Вычисление множителя для текущего клика
  const getMultiplierForClick = useCallback((clickNumber: number) => {
    if (clickNumber <= 3) {
      return 0.1 + Math.random() * 0.2; // 0.1-0.3
    } else if (clickNumber <= 6) {
      return 1 + Math.random() * 1; // 1-2
    } else {
      // Экспоненциальный рост
      const base = Math.pow(1.5, clickNumber - 6);
      return 10 + base * (10 + Math.random() * 10); // 10-20 и выше
    }
  }, []);

  // Запуск игры
  const startGame = useCallback(() => {
    setGameState('animating');
    setMultiplier(1);
    setClickCount(0);
    setStarsVisible(false);
    setStars(generateStars(1));
    
    // Через 17.2 секунды (172 кадра * 100мс) переходим в состояние игры
    setTimeout(() => {
      setGameState('playing');
      setStarsVisible(true);
      
      // Вращение звезд
      const rotateStars = () => {
        rotationAngle.current += 0.001; // Скорость вращения (замедлено в 20 раз)
        setStars(prevStars => prevStars.map(star => ({
          ...star,
          angle: star.angle + 0.001
        })));
        starRotationRef.current = requestAnimationFrame(rotateStars);
      };
      rotateStars();
    }, 17200); // 17.2 секунды
  }, [generateStars]);

  // Клик по звезде
  const handleStarClick = useCallback((star: Star) => {
    if (gameState !== 'playing') return;
    
    if (star.type === 'dangerous') {
      // Опасная звезда - провальный раунд
      const newContribution = Math.max(1.0, currentContribution - 0.1);
      setCurrentContribution(newContribution);
      setMultiplier(newContribution);
      
      // Начинаем анимацию завершения
      setMultiplier(1);
      setGameState('ending');
      setStarsVisible(false);
      
      // Очищаем анимации звезд
      if (starRotationRef.current) cancelAnimationFrame(starRotationRef.current);
      
      // Через 1.2 секунды (12 кадров * 100мс) переходим в состояние ожидания
      setTimeout(() => {
        setGameState('waiting');
      }, 1200);
      
      return;
    }
    
    // Безопасная звезда - увеличиваем множитель
    const newClickCount = clickCount + 1;
    const multiplierIncrease = getMultiplierForClick(newClickCount);
    const newMultiplier = multiplier + multiplierIncrease;
    
    setMultiplier(newMultiplier);
    setClickCount(newClickCount);
    
    // Генерируем новые звезды для следующего раунда
    const newRound = Math.min(newClickCount + 1, 10);
    setStars(generateStars(newRound));
  }, [gameState, clickCount, multiplier, getMultiplierForClick, generateStars]);

  // Завершение игры с сохранением множителя
  const finishGame = useCallback(() => {
    if (multiplier > 1) {
      // Успешный раунд
      const newContribution = currentContribution + 0.2;
      setCurrentContribution(newContribution);
      setMultiplier(newContribution);
      
      setSavedMultiplier(multiplier);
      setSavedMultiplierExpiry(Date.now() + 60000); // 1 минута
    }
    
    setGameState('waiting');
    setMultiplier(1);
    setClickCount(0);
    setStars([]);
    setStarsVisible(false);
    
    // Очищаем анимации звезд
    if (starRotationRef.current) cancelAnimationFrame(starRotationRef.current);
  }, [multiplier, currentContribution]);

  // Рестарт за 10% от state.total
  const restartGame = useCallback(() => {
    const cost = total * 0.1;
    if (resources >= cost) {
      // Списываем ресурсы
      dispatch(updateResources({ resources: { [COMMON]: -cost } }));
      // Вклад сохраняется при перезапуске
      startGame();
    }
  }, [startGame, total, resources, dispatch]);

  // Очистка при размонтировании
  useEffect(() => {
    return () => {
      if (starRotationRef.current) cancelAnimationFrame(starRotationRef.current);
    };
  }, []);

  const displayMultiplier = (gameState === 'ending' || (gameState === 'waiting' && multiplier === 0)) ? 0 : multiplier;
  const timeLeft = savedMultiplierExpiry ? Math.max(0, savedMultiplierExpiry - Date.now()) : 0;

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <h3 className={styles.title}>{t('projects.wormhole.title')}</h3>
        <div className={styles.stats}>
          <span>{t('projects.wormhole.multiplier', { value: displayMultiplier.toFixed(2) })}</span>
          {savedMultiplier && timeLeft > 0 && (
            <span className={styles.savedTimer}>
              {t('projects.wormhole.saved_timer', { value: savedMultiplier.toFixed(2), seconds: Math.ceil(timeLeft / 1000) })}
            </span>
          )}
        </div>
      </div>

      <div className={styles.gameArea}>
        {/* Фоновая анимация */}
        <div 
          className={`${styles.background} ${
            gameState === 'animating' ? styles.animating :
            gameState === 'playing' ? styles.opened :
            gameState === 'ending' ? styles.closing :
            ''
          }`}
        />

        {/* Кнопка старт */}
        {gameState === 'waiting' && (
          <div className={styles.startContainer}>
          <h4>{t('projects.wormhole.instructions')}</h4>
          <button className={styles.startButton} onClick={startGame}>
            {t('projects.wormhole.start')}
          </button>
          </div>
        )}

        {/* Звезды */}
        {gameState === 'playing' && (
          <div className={`${styles.starsContainer} ${starsVisible ? styles.visible : ''}`}>
            {stars.map(star => {
              const x = 50 + Math.cos(star.angle) * star.radius;
              const y = 50 + Math.sin(star.angle) * star.radius;
              
              return (
                <div
                  key={star.id}
                  className={classNames(styles.star, styles[`star${star.visualType}`])}
                  style={{
                    left: `${x}%`,
                    top: `${y}%`,
                  }}
                  onClick={() => handleStarClick(star)}
                />
              );
            })}
          </div>
        )}

        {/* Кнопка завершить */}
        {gameState === 'playing' && (
          <button className={styles.finishButton} onClick={finishGame}>
            {t('projects.wormhole.take_result')}
          </button>
        )}

        {/* Экран окончания игры - показываем только если нет активной анимации */}
        {gameState === 'waiting' && multiplier === 0 && (
          <div className={styles.gameOver}>
            <h4>{t('projects.wormhole.game_over')}</h4>
            <p>{t('projects.wormhole.multiplier_reset')}</p>
            <button className={styles.restartButton} onClick={restartGame}>
              {t('projects.wormhole.restart')}
            </button>
          </div>
        )}
      </div>
    </div>
  );
};