import React, { useMemo, useState, useEffect } from 'react';
import styles from './index.module.scss';
import { useAppSelector } from '../../app/hooks';
import { selectedCountry, selectStage, selectDeathTimer, selectTalentPoints, selectSpentTalentPoints } from '../../app/gameSlice';
import classNames from 'classnames';
import { AnimatedSprite } from '../AnimatedSprite';
import { SettingsMenu } from '../SettingsMenu';
import { useI18n } from '../../hooks/useI18n';

interface TooltipData {
  isVisible: boolean;
  type: 'sphere' | 'main' | 'country' | 'earth' | 'timer' | 'talents';
  sphere?: string;
  position: { x: number; y: number };
}

// Убираем статический tooltipInfo, заменяем на переводы

const ResourcesHeader: React.FC<{ wireframe?: boolean }> = ({ wireframe = false }) => {
  const countryName = useAppSelector(selectedCountry);
  const stage = useAppSelector(selectStage);
  const deathTimer = useAppSelector(selectDeathTimer);
  const talentPoints = useAppSelector(selectTalentPoints);
  const spentTalentPoints = useAppSelector(selectSpentTalentPoints);
  const { t } = useI18n();
  const [tooltip, setTooltip] = useState<TooltipData>({ 
    isVisible: false,
    type: 'sphere',
    position: { x: 0, y: 0 } 
  });
  const [, setUpdate] = useState(0); // Для принудительного обновления таймера

  const handleMouseEnter = (type: 'sphere' | 'main' | 'country' | 'earth' | 'timer' | 'talents', sphere?: string, e?: React.MouseEvent) => {
    if (!e) return;
    
    const rect = e.currentTarget.getBoundingClientRect();
    setTooltip({
      isVisible: true,
      type,
      sphere,
      position: { 
        x: rect.left, 
        y: rect.bottom + 5 
      }
    });
  };

  const handleMouseLeave = () => {
    setTooltip({ ...tooltip, isVisible: false });
  };

  // Динамическое содержимое тултипа
  const getTooltipContent = () => {
    switch (tooltip.type) {
      case 'sphere':
        if (tooltip.sphere) {
          return t(`header.tooltips.${tooltip.sphere}`) || `${tooltip.sphere}: Развивайте эту сферу через специальные улучшения.`;
        }
        return '';
      case 'country':
        return t('header.tooltips.country');
      case 'earth':
        return t('header.tooltips.earth');
      case 'timer':
        const timeRemaining = getGameTimeRemaining();
        return timeRemaining 
          ? t('header.tooltips.timer', { years: timeRemaining.years, months: timeRemaining.months })
          : t('header.tooltips.timer', { years: '?', months: '?' });
      case 'talents':
        return t('header.tooltips.talents', { available: talentPoints, spent: spentTalentPoints });
      default:
        return '';
    }
  };
  // Функция для расчета оставшегося времени в игровых годах
  const getGameTimeRemaining = () => {
    if (!deathTimer.isActive || stage !== 1) return null;
    
    // Используем прогресс вместо реального времени
    const progress = deathTimer.progress || 0;
    
    if (progress >= 1.0) return { years: 0, months: 0 };
    
    // Рассчитываем оставшиеся игровые годы на основе прогресса
    const yearsElapsed = progress * deathTimer.gameYears;
    const yearsRemaining = deathTimer.gameYears - yearsElapsed;
    
    const years = Math.floor(yearsRemaining);
    const months = Math.floor((yearsRemaining - years) * 12);
    
    return { years, months };
  };

  // Функция для определения критичности времени
  const getTimeCriticalityClass = () => {
    const timeRemaining = getGameTimeRemaining();
    if (!timeRemaining) return '';
    
    const { years } = timeRemaining;
    
    if (years <= 0) {
      return styles.timeCritical; // Критическое время - быстрая пульсация
    } else if (years <= 2) {
      return styles.timeUrgent; // Срочное время - средняя пульсация
    } else if (years <= 5) {
      return styles.timeWarning; // Предупреждение - медленная пульсация
    } else if (years <= 10) {
      return styles.timeAlert; // Начальное предупреждение - очень медленная пульсация
    }
    
    return ''; // Нормальное время - без пульсации
  };

  // Функция для расчета текущей игровой даты
  const getCurrentGameDate = () => {
    if (!deathTimer.isActive || stage !== 1) return null;
    
    // Используем прогресс таймера вместо реального времени
    const progress = deathTimer.progress || 0;
    const yearsElapsed = progress * deathTimer.gameYears;
    
    const startDate = new Date(deathTimer.realStartDate);
    const currentYear = startDate.getFullYear() + Math.floor(yearsElapsed);
    const currentMonth = startDate.getMonth() + Math.floor((yearsElapsed - Math.floor(yearsElapsed)) * 12);
    
    // Обработка переполнения месяцев
    const finalYear = currentYear + Math.floor(currentMonth / 12);
    const finalMonth = currentMonth % 12;
    
    return new Date(finalYear, finalMonth);
  };

  const getRandomEarth = useMemo(() => {
    const names = ['𒆠', 'Erṣetu', 'Terra', 'Miðgarðr', 'Tlālticpac', '🌍']
    return Math.random() <= 0.05 ? names[Math.floor(Math.random() * names.length)] : 'Earth';
  }, []);



  // Обновляем таймер каждую секунду
  useEffect(() => {
    if (stage === 1 && deathTimer.isActive) {
      const interval = setInterval(() => {
        setUpdate(prev => prev + 1);
      }, 1000);

      return () => clearInterval(interval);
    }
  }, [stage, deathTimer.isActive]);

  return (
    <div className={classNames(styles.resourcesHeader, { [styles.wireframe]: wireframe })}>
      <div className={styles.talentPointsContainer}>
      <div className={styles.icon}>
          <AnimatedSprite
            id="talent-points-star"
            standalone={true}
            clipWidth={40}
            clipHeight={40}
            width={32}
            height={50}
            duration="0.3s"
            style={
              {
                width: 40,
                height: 40,
              }
            }
          />
        </div>
        <div 
          className={styles.talentPoints}
          onMouseEnter={(e) => handleMouseEnter('talents', undefined, e)}
          onMouseLeave={handleMouseLeave}
        >
          <div className={styles.talentValue}>
            <span className={styles.available}>{talentPoints}</span>
          </div>
        </div>
      </div>


      
      <div 
        className={styles.countryInfo}
        onMouseEnter={(e) => handleMouseEnter(
          stage === 2 ? 'earth' : (stage === 1 && deathTimer.isActive ? 'timer' : 'country'), 
          undefined, 
          e
        )}
        onMouseLeave={handleMouseLeave}
      >
        {(() => {
          if (stage === 2) {
            return getRandomEarth;
          } else if (stage === 1 && deathTimer.isActive) {
            const currentDate = getCurrentGameDate();
            if (currentDate) {
              // Получаем месяц и год из даты
              const monthIndex = currentDate.getMonth();
              const year = currentDate.getFullYear();
              
              // Получаем название месяца из переводов
              const monthNames = [
                t('header.date.months.january'),
                t('header.date.months.february'),
                t('header.date.months.march'),
                t('header.date.months.april'),
                t('header.date.months.may'),
                t('header.date.months.june'),
                t('header.date.months.july'),
                t('header.date.months.august'),
                t('header.date.months.september'),
                t('header.date.months.october'),
                t('header.date.months.november'),
                t('header.date.months.december')
              ];
              
              const month = monthNames[monthIndex];
              const yearStr = t('header.date.year', { year });
              return (
                <div className={classNames(styles.dateDisplay, getTimeCriticalityClass())}>
                  <span className={styles.monthPart}>{month}</span>
                  <span className={styles.yearPart}>{yearStr}</span>
                </div>
              );
            }
            return t('header.tooltips.unknown_date');
          } else {
            return countryName || t('header.tooltips.select_country');
          }
        })()}
      </div>
      
      <SettingsMenu />
      
      
      {tooltip.isVisible && (
        <div 
          className={styles.tooltip} 
          style={{ 
            left: `${tooltip.position.x}px`, 
            top: `${tooltip.position.y}px` 
          }}
        >
          {getTooltipContent()}
        </div>
      )}
    </div>
  );
};

export default ResourcesHeader; 