import React from 'react';
import classNames from 'classnames';
import { Position } from '../../utils/TrajectoryCalculator';
import styles from './index.module.scss';

interface TrajectoryLineProps {
  shipPosition: Position;
  targetPosition: Position;
  isVisible: boolean;
  rotation: number;
  length: number;
}

export const TrajectoryLine: React.FC<TrajectoryLineProps> = ({
  shipPosition,
  targetPosition,
  isVisible,
  rotation,
  length
}) => {
  if (!isVisible) {
    return null;
  }

  // Вычисляем расстояние между кораблем и целевой позицией
  const deltaY = (targetPosition.y - shipPosition.y);
  
  // Для вертикального направления (корабль возвращается на курс) используем только deltaY
  const distance = Math.abs(deltaY/length);
  
  // Корабль выше или ниже цели?
  const isShipAboveTarget = shipPosition.y < targetPosition.y;
  
  // Вычисляем длину линии
  const lineLength = Math.max(distance, 10); // Минимум 10%

  return (
    <div
      className={classNames(styles.trajectoryLine, {
        [styles.visible]: isVisible
      })}
      style={{
        position: 'absolute',
        left: `${shipPosition.x}%`,
        top: `${isShipAboveTarget ? shipPosition.y : targetPosition.y}%`,
        width: `4px`,
        height: `${lineLength}px`,
        transform: `translate(-50px, 20px) rotate(-90deg)`,
        transformOrigin: 'right top'
      }}
    >
      <div className={styles.lineCore} />
      <div className={styles.lineGlow} />

      {/* Arrow indicator pointing toward target */}
      <div 
        className={styles.arrow}
        style={{
          transform: `translateX(-50%) rotate(${isShipAboveTarget ? '180deg' : '0deg'})`,
          [isShipAboveTarget ? 'bottom' : 'top']: '0px'
        }}
      />

      {/* Pulsing dots along the line */}
      <div className={styles.pulsingDot} style={{ top: '25%' }} />
      <div className={styles.pulsingDot} style={{ top: '50%' }} />
      <div className={styles.pulsingDot} style={{ top: '75%' }} />
    </div>
  );
};