import React, { useState } from 'react';
import styles from './index.module.scss';
import { useAppSelector } from '../../app/hooks';
import { selectResources, selectTotalAutoIncome, selectManualClickPower, selectAutoClickPower, selectStage, selectWarpTravel, selectResourceGenerationDisabled } from '../../app/gameSlice';
import CountUp from '../CountUp';
import classNames from 'classnames';
import { SHIP_BASE_DAMAGE_RATE } from '../../app/constants';
import { useI18n } from '../../hooks/useI18n';

interface TooltipData {
  isVisible: boolean;
  position: { x: number; y: number };
}

const MainResources: React.FC = () => {
  const resources = useAppSelector(selectResources);
  const clickPower = useAppSelector(selectManualClickPower);
  const autoClickPower = useAppSelector(selectAutoClickPower);
  const totalAutoIncome = useAppSelector(selectTotalAutoIncome);
  const stage = useAppSelector(selectStage);
  const warpTravel = useAppSelector(selectWarpTravel);
  const resourceGenerationDisabled = useAppSelector(selectResourceGenerationDisabled);
  const { t } = useI18n();
  const [tooltip, setTooltip] = useState<TooltipData>({ 
    isVisible: false,
    position: { x: 0, y: 0 } 
  });

  const handleMouseEnter = (e: React.MouseEvent) => {
    const rect = e.currentTarget.getBoundingClientRect();
    setTooltip({
      isVisible: true,
      position: { 
        x: rect.left, 
        y: rect.bottom + 5 
      }
    });
  };

  const handleMouseLeave = () => {
    setTooltip({ ...tooltip, isVisible: false });
  };

  const getCurrentCPS = () => {
    return (autoClickPower + totalAutoIncome).toFixed(1);
  };

  const getWarpCost = () => {
    if (!warpTravel?.isActive) return 0;
    
    return warpTravel.warpCost;
  };

  return (
    <>
      <div 
        className={classNames(styles.mainResources, {
          [styles.stageTwo]: stage === 2
        })}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        <div className={styles.icon}>💰</div>
        <div className={styles.resourcesContainer}>
          <CountUp value={resources} suffix="₿" duration={950} showColors className={styles.value} />
          <div className={classNames(styles.cpsDisplay, {
            [styles.disabled]: resourceGenerationDisabled
          })}>
            {resourceGenerationDisabled ? (
              <span className={styles.disabledText}>{t('resources.generation_paused')}</span>
            ) : (
              <>
                {getCurrentCPS()}{t('resources.per_second')}
                {warpTravel?.isActive && (
                  <span className={styles.warpCost}>{t('resources.warp_cost', { cost: getWarpCost().toFixed(1) })}</span>
                )}
              </>
            )}
          </div>
        </div>
      </div>
      
      {tooltip.isVisible && (
        <div 
          className={styles.tooltip} 
          style={{ 
            left: `${tooltip.position.x}px`, 
            top: `${tooltip.position.y}px` 
          }}
        >
          {resourceGenerationDisabled ? (
            <span dangerouslySetInnerHTML={{ __html: t('resources.tooltip_paused') }} />
          ) : (
            <span dangerouslySetInnerHTML={{ 
              __html: t('resources.tooltip_active', { 
                power: Math.round(clickPower), 
                cps: getCurrentCPS() 
              }) 
            }} />
          )}
        </div>
      )}
    </>
  );
};

export default MainResources; 