/**
 * TrajectoryCalculator - Utility class for calculating ship trajectory positions
 * Used in the warp emergency system to handle ship positioning and course corrections
 */

export interface Position {
  x: number;
  y: number;
}

export class TrajectoryCalculator {
  /**
   * Calculates the normal position of the ship on the standard trajectory
   * Uses a quadratic Bezier curve from bottom-left to top-right
   * @param progress - Progress along trajectory (0-100)
   * @returns Position object with x,y coordinates as percentages
   */
  static calculateNormalPosition(progress: number): Position {
    // Validate input
    if (progress < 0 || progress > 100) {
      throw new Error('Progress must be between 0 and 100');
    }

    // Trajectory control points
    const startX = 5, startY = 90;    // Bottom-left start
    const endX = 95, endY = 5;        // Top-right end
    const controlX = 25, controlY = 20; // Control point for curve

    // Convert progress to t parameter (0-1)
    const t = progress / 100;

    // Quadratic Bezier curve calculation
    const x = Math.pow(1 - t, 2) * startX + 2 * (1 - t) * t * controlX + Math.pow(t, 2) * endX;
    const y = Math.pow(1 - t, 2) * startY + 2 * (1 - t) * t * controlY + Math.pow(t, 2) * endY;

    return { x, y };
  }

  /**
   * Calculates a random emergency position when ship is thrown off course
   * Position is always above the normal trajectory to simulate being "lost in space"
   * @param currentProgress - Current progress along normal trajectory (0-100)
   * @param warpResourcesEarned - Amount of warp resources earned (affects deviation distance)
   * @returns Emergency position coordinates
   */
  static calculateEmergencyPosition(currentProgress: number, warpResourcesEarned: number): Position {
    // Validate inputs with fallbacks
    const validProgress = Math.max(0, Math.min(100, currentProgress || 0));
    const validResources = Math.max(0, warpResourcesEarned || 0);

    try {
      const normalPos = this.calculateNormalPosition(validProgress);
      
      // Calculate deviation distance based on resources earned
      // More resources = further deviation (ship was in warp longer)
      const deviationDistance = (validResources / 1000000) * 2; // x2 multiplier
      
      // Random angle in upper hemisphere (0 to π radians)
      const angle = Math.random() * Math.PI;
      
      // Limit maximum deviation to prevent off-screen positioning
      const distance = Math.min(deviationDistance, 30);
      
      const emergencyPos = {
        x: normalPos.x + Math.cos(angle) * distance,
        y: Math.max(5, normalPos.y - Math.sin(angle) * distance) // Never go above 5% (top of screen)
      };

      // Ensure position is within screen bounds
      return {
        x: Math.max(2, Math.min(98, emergencyPos.x)),
        y: Math.max(2, Math.min(98, emergencyPos.y))
      };
    } catch (error) {
      // Fallback to safe position if calculation fails
      console.warn('Emergency position calculation failed, using fallback:', error);
      return { x: 50, y: 30 }; // Safe middle position
    }
  }

  /**
   * Finds the closest point on the normal trajectory to a given position
   * Used to determine where the ship should return to after emergency exit
   * @param position - Current ship position
   * @returns Object containing closest trajectory point and its progress value
   */
  static findClosestTrajectoryPoint(position: Position): { point: Position, progress: number } {
    // Validate input
    if (!position || typeof position.x !== 'number' || typeof position.y !== 'number') {
      throw new Error('Position must be an object with numeric x and y properties');
    }

    let minDistance = Infinity;
    let closestPoint = { x: 0, y: 0 };
    let closestProgress = 0;

    // Check trajectory points with 1% step for accuracy
    for (let progress = 0; progress <= 100; progress += 1) {
      const trajectoryPoint = this.calculateNormalPosition(progress);
      
      // Calculate Euclidean distance
      const distance = Math.sqrt(
        Math.pow(position.x - trajectoryPoint.x, 2) + 
        Math.pow(position.y - trajectoryPoint.y, 2)
      );

      if (distance < minDistance) {
        minDistance = distance;
        closestPoint = trajectoryPoint;
        closestProgress = progress;
      }
    }

    return { point: closestPoint, progress: closestProgress };
  }

  /**
   * Calculates the distance between two positions
   * @param pos1 - First position
   * @param pos2 - Second position
   * @returns Distance between positions
   */
  static calculateDistance(pos1: Position, pos2: Position): number {
    return Math.sqrt(
      Math.pow(pos2.x - pos1.x, 2) + 
      Math.pow(pos2.y - pos1.y, 2)
    );
  }

  /**
   * Interpolates between two positions based on progress
   * Used for smooth return-to-course animations
   * @param startPos - Starting position
   * @param endPos - Target position
   * @param progress - Animation progress (0-1)
   * @returns Interpolated position
   */
  static interpolatePosition(startPos: Position, endPos: Position, progress: number): Position {
    // Validate inputs
    if (progress < 0 || progress > 1) {
      throw new Error('Progress must be between 0 and 1');
    }

    return {
      x: startPos.x + (endPos.x - startPos.x) * progress,
      y: startPos.y + (endPos.y - startPos.y) * progress
    };
  }
}