import React, { useMemo, useEffect, useState, useCallback } from 'react';
import styles from './Ship.module.scss';
import { useAppSelector } from '../../app/hooks';
import { selectGame, selectWarpTravel } from '../../app/gameSlice';
import { getAvailableGames, isGameAvailable, getRemainingCooldown, ExtendedMiniGame } from '../../MiniGames';
import { TrajectoryCalculator } from '../../utils/TrajectoryCalculator';
import { TrajectoryLine } from '../TrajectoryLine';
import RoomButton from './RoomButton';

// Типы кораблей
export type ShipVariant = 'default' | 'ftl' | 'warp';

// Функция для определения правильного расширения файла
const getFileExtension = (shipVariant: ShipVariant, fileType: 'top' | 'interior'): string => {
  const extensions: Record<ShipVariant, Record<string, string>> = {
    default: { top: 'avif', interior: 'avif' },
    ftl: { top: 'webp', interior: 'avif' },
    warp: { top: 'webp', interior: 'webp' }
  };
  return extensions[shipVariant][fileType];
};

// Интерфейс для определения областей комнат (clip-path)
interface RoomClipPaths {
  [gameId: string]: string;
}

// Определяем области комнат для каждого варианта корабля
// Координаты подобраны под реальные изображения интерьера
const ROOM_CLIP_PATHS: Record<ShipVariant, RoomClipPaths> = {
  default: {
    'restart_core': 'polygon(40% 45%, 60% 45%, 60% 70%, 40% 70%)', // Центральная комната (мостик)
    'hack_airlock': 'polygon(72% 40%, 88% 40%, 88% 65%, 72% 65%)', // Правая комната (грузовой отсек)
    'exotic_synthesis': 'polygon(12% 40%, 28% 40%, 28% 65%, 12% 65%)', // Левая комната (лаборатория)
    'alien_code_breaker': 'polygon(40% 20%, 60% 20%, 60% 40%, 40% 40%)', // Верхняя комната (командный центр)
    'tactical_analysis': 'polygon(65% 20%, 80% 20%, 80% 35%, 65% 35%)', // Верхняя правая (тактический центр)
    'resource_optimization': 'polygon(15% 75%, 35% 75%, 35% 90%, 15% 90%)', // Нижняя левая (инженерный)
  },
  ftl: {
    'restart_core': 'polygon(42% 48%, 58% 48%, 58% 68%, 42% 68%)',
    'hack_airlock': 'polygon(70% 35%, 85% 35%, 85% 58%, 70% 58%)',
    'exotic_synthesis': 'polygon(15% 35%, 30% 35%, 30% 58%, 15% 58%)',
    'alien_code_breaker': 'polygon(42% 22%, 58% 22%, 58% 42%, 42% 42%)',
    'tactical_analysis': 'polygon(70% 22%, 82% 22%, 82% 32%, 70% 32%)',
    'resource_optimization': 'polygon(18% 72%, 32% 72%, 32% 85%, 18% 85%)',
  },
  warp: {
    'restart_core': 'polygon(35% 52%, 65% 52%, 65% 78%, 35% 78%)',
    'hack_airlock': 'polygon(78% 42%, 92% 42%, 92% 72%, 78% 72%)',
    'exotic_synthesis': 'polygon(8% 42%, 22% 42%, 22% 72%, 8% 72%)',
    'alien_code_breaker': 'polygon(35% 28%, 65% 28%, 65% 48%, 35% 48%)',
    'tactical_analysis': 'polygon(72% 28%, 85% 28%, 85% 38%, 72% 38%)',
    'resource_optimization': 'polygon(15% 82%, 30% 82%, 30% 95%, 15% 95%)',
  }
};

interface ShipProps {
  progress: number; // от 0 до 100
  className?: string;
  onGameStart?: (game: ExtendedMiniGame) => void;
}

const Ship: React.FC<ShipProps> = ({ progress, className, onGameStart }) => {
  const game = useAppSelector(selectGame);
  const warpTravel = useAppSelector(selectWarpTravel);
  const [, setAnimationTick] = useState(0);

  // Определяем тип корабля на основе состояния игры
  const shipVariant: ShipVariant = useMemo(() => {
    if (warpTravel?.isUnlocked) return 'warp';
    if (game.cosmicCivilization.FTL) return 'ftl';
    return 'default';
  }, [game.cosmicCivilization.FTL, warpTravel?.isUnlocked]);

  // Получаем все доступные игры
  const availableGames = useMemo(() => {
    return getAvailableGames(game);
  }, [game.secondStage, game.stage]);

  // Для каждой игры определяем её состояние
  const gameStates = useMemo(() => {
    return availableGames.map(miniGame => ({
      game: miniGame,
      isAvailable: isGameAvailable(miniGame, game),
      cooldown: getRemainingCooldown(miniGame, game)
    }));
  }, [availableGames, game.miniGamesState, game]);

  // Ограничиваем прогресс от 0 до 100
  const normalizedProgress = useMemo(() => {
    return Math.max(0, Math.min(100, progress));
  }, [progress]);

  // Рассчитываем позицию корабля
  const shipPosition = useMemo(() => {
    return TrajectoryCalculator.calculateNormalPosition(normalizedProgress);
  }, [normalizedProgress]);

  // Функция easing для плавной анимации
  const easeInOutCubic = useCallback((t: number): number => {
    return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
  }, []);

  // Рассчитываем смещение по Y для аварийного состояния
  const yOffset = (() => {
    if (!warpTravel?.isOffCourse) {
      return 0;
    }

    if (warpTravel.returnStartTime && warpTravel.returnDuration) {
      const now = Date.now();
      const elapsed = now - warpTravel.returnStartTime;
      const returnProgress = Math.min(1, elapsed / warpTravel.returnDuration);
      const easedProgress = easeInOutCubic(returnProgress);
      return -200 + (easedProgress * 200);
    }

    return -200;
  })();

  // useEffect для обновления анимации возврата на курс
  useEffect(() => {
    if (warpTravel?.isOffCourse && warpTravel.returnStartTime && warpTravel.returnDuration) {
      let animationFrameId: number;
      
      const animate = () => {
        const now = Date.now();
        const elapsed = now - warpTravel.returnStartTime!;
        
        if (elapsed < warpTravel.returnDuration!) {
          setAnimationTick(prev => prev + 1);
          animationFrameId = requestAnimationFrame(animate);
        }
      };

      animationFrameId = requestAnimationFrame(animate);

      return () => {
        if (animationFrameId) {
          cancelAnimationFrame(animationFrameId);
        }
      };
    }
  }, [warpTravel?.isOffCourse, warpTravel?.returnStartTime, warpTravel?.returnDuration]);

  // Рассчитываем угол поворота корабля
  const shipRotation = (() => {
    if (warpTravel?.isOffCourse) {
      return -90;
    }
    return 45 - (normalizedProgress / 100) * 65;
  })();

  // Обработчик запуска игры
  const handleGameStart = (selectedGame: ExtendedMiniGame) => {
    if (onGameStart) {
      onGameStart(selectedGame);
    }
  };

  // Получаем clip-paths для текущего варианта корабля
  const currentClipPaths = ROOM_CLIP_PATHS[shipVariant];

  return (
    <div
      className={`${styles.shipContainer} ${className || ''} ${warpTravel?.isOffCourse ? styles.offCourse : ''}`}
      style={{
        left: `${shipPosition.x}%`,
        top: `${shipPosition.y}%`,
        transform: `translate(-50%, calc(-50% + ${yOffset}%)) rotate(${shipRotation}deg)`
      }}
    >
      {/* Изображение корабля сверху (всегда видимое) */}
      <div 
        className={styles.shipExterior}
        style={{
          backgroundImage: `url(${require(`../../assets/ship/${shipVariant}/top.${getFileExtension(shipVariant, 'top')}`)})`
        }}
      />

      {/* Изображение интерьера корабля (показывается под комнатами) */}
      <div 
        className={styles.shipInterior}
        style={{
          backgroundImage: `url(${require(`../../assets/ship/${shipVariant}/interior.${getFileExtension(shipVariant, 'interior')}`)})`
        }}
      />

      {/* Траектория возврата на курс */}
      <TrajectoryLine
        shipPosition={{ 
          x: shipPosition.x, 
          y: shipPosition.y + (yOffset / 4)
        }}
        targetPosition={{ 
          x: shipPosition.x, 
          y: shipPosition.y
        }}
        isVisible={warpTravel?.isOffCourse || false}
        rotation={0}
        length={yOffset/300}
      />

      {/* Отображаем комнаты только если корабль на курсе */}
      {!warpTravel?.isOffCourse && gameStates.map(({ game: miniGame, isAvailable, cooldown }) => (
        <RoomButton
          key={miniGame.id}
          game={miniGame}
          isAvailable={isAvailable}
          cooldown={cooldown}
          onGameStart={handleGameStart}
          roomClipPath={currentClipPaths[miniGame.id] || 'polygon(0% 0%, 100% 0%, 100% 100%, 0% 100%)'}
        />
      ))}
    </div>
  );
};

export default Ship;