import React, { useMemo, useState } from "react";
import ReactDOM from "react-dom";
import styles from "./shop.module.scss";
import { useAppDispatch, useAppSelector } from "../../app/hooks";
import { selectUpgrades, buyUpgrade, selectResources, selectUpgradeMultipliers, selectMultipliers, selectAutoClickPower, selectTotalAutoIncome, selectTotal, selectProjectMultiplier } from "../../app/gameSlice";
import { UPGRADES } from "../../Upgrades";
import CountUp from "../../components/CountUp";
import { COMMON, ECONOMY, FAITH, MANUAL, SCIENCE } from "../../app/constants";
import { calculateUpgradeCost, calculateEffectiveCPS, calculateTotalUpgradeCPS } from "../../app/utils";
import { useI18n } from "../../hooks/useI18n";

// Типы режимов покупки
type PurchaseMode = 'x1' | 'x10' | 'max';

// Функция для расчета стоимости покупки нескольких уровней
const calculateBulkUpgradeCost = (
  currentLevel: number,
  targetLevel: number,
  baseCost: number,
  growthRate: number,
  transitionLevel: number,
  linearIncrement: number
): number => {
  let totalCost = 0;
  for (let level = currentLevel; level < targetLevel; level++) {
    totalCost += calculateUpgradeCost(level, {
      baseCost,
      growthRate,
      transitionLevel,
      linearIncrement
    });
  }
  return totalCost;
};

// Функция для расчета максимального количества уровней, которые можно купить
const calculateMaxAffordableLevels = (
  currentLevel: number,
  availableResources: number,
  baseCost: number,
  growthRate: number,
  transitionLevel: number,
  linearIncrement: number
): number => {
  let maxLevels = 0;
  let totalCost = 0;
  
  while (totalCost <= availableResources) {
    const nextLevelCost = calculateUpgradeCost(currentLevel + maxLevels, {
      baseCost,
      growthRate,
      transitionLevel,
      linearIncrement
    });
    
    if (totalCost + nextLevelCost <= availableResources) {
      totalCost += nextLevelCost;
      maxLevels++;
    } else {
      break;
    }
  }
  
  return maxLevels;
};

// Компонент для отрисовки фона с иконками
const UpgradeBackground: React.FC<{ icon: string; level: number }> = ({ icon, level }) => {
  // Создаем массив иконок в количестве, равном уровню апгрейда
  const icons = Array.from({ length: Math.min(level, 100) }, (_, index) => (
    <span key={index} className={styles.upgradeIconBg}>{icon}</span>
  ));
  
  return <div className={styles.upgradeBackground}>{icons}</div>;
};

// Интерфейс для тултипа
interface TooltipData {
  isVisible: boolean;
  upgradeId: string;
  position: { x: number; y: number };
}

// Компонент тултипа для апгрейдов
const UpgradeTooltip: React.FC<{ 
  tooltip: TooltipData; 
  upgrade: any; 
  totalCPS: number;
}> = ({ tooltip, upgrade, totalCPS }) => {
  const { t } = useI18n();
  
  if (!tooltip.isVisible || !upgrade) return null;

  // Функция для определения типа действия апгрейда
  const getUpgradeAction = (sphere: string) => {
    switch (sphere) {
      case MANUAL:
        return t('shop.tooltip_detailed.enhances_click'); // 'Усиливает ваш клик';
      case COMMON:
      case ECONOMY:
      case SCIENCE:
      case FAITH:
        return t('shop.tooltip_detailed.mines_resources'); // 'Добывает ресурсы автоматически';
      
      default:
        return t('shop.tooltip_detailed.improves_production'); // 'Улучшает производство';
    }
  };

  // Рендерим тултип через портал прямо в body
  return ReactDOM.createPortal(
    <div 
      className={styles.upgradeTooltip}
      style={{ 
        left: `${tooltip.position.x}px`, 
        top: `${tooltip.position.y}px`,
        position: 'fixed',
        zIndex: 1,
        backgroundColor: 'var(--gunmetal)',
        color: 'var(--alabaster)',
        padding: '12px',
        borderRadius: '8px',
        border: '1px solid var(--cinnabar)',
        maxWidth: '280px',
        boxShadow: '0 4px 12px rgba(0, 0, 0, 0.5)',
        pointerEvents: 'none'
      }}
    >
      <div style={{ fontWeight: 'bold', marginBottom: '8px', fontSize: '1.1em' }}>
        {upgrade.icon} {upgrade.name}
      </div>
      
      <div style={{ marginBottom: '6px', color: 'var(--cinnabar)' }}>
        {getUpgradeAction(upgrade.sphere)}
      </div>
      <div>
        {t('shop.tooltip_detailed.income')}: {upgrade.effectiveCPS.toFixed(1)} {t('shop.tooltip_detailed.per_second')}
      </div>

      {upgrade.level > 0 && (
        <div style={{ marginBottom: '6px' }}>
          <strong>{t('shop.tooltip_detailed.level_gives', { level: upgrade.level })}:</strong> {upgrade.totalCPS.toFixed(1)}
          {t('shop.tooltip_detailed.per_second')}
        </div>
      )}

      {process.env.NODE_ENV === 'development' && upgrade.effectiveCPS > 0 && (<>
        <div style={{ 
          marginBottom: '6px', 
          color: 'lightblue', 
          fontSize: '0.9em' 
        }}>
          <strong>{t('shop.tooltip_detailed.roi')}:</strong> {(upgrade.cost / (upgrade.effectiveCPS + totalCPS)).toFixed(1)} {t('shop.tooltip_detailed.seconds')}
        </div>
        <div style={{ 
          marginBottom: '6px', 
          color: 'lightblue', 
          fontSize: '0.9em' 
        }}>
          <strong>{t('shop.tooltip_detailed.mining_price')}:</strong> {(upgrade.cost / (upgrade.effectiveCPS)).toFixed(1)} ₿
        </div>
        </>
      )}
      
      {upgrade.flavorText && (
        <div style={{ 
          fontStyle: 'italic', 
          color: 'var(--alabaster)', 
          opacity: 0.8,
          marginTop: '8px',
          fontSize: '0.9em'
        }}>
          "{t(`upgrades:${upgrade.id}.flavorText`, { defaultValue: upgrade.flavorText })}"
        </div>
      )}
    </div>,
    document.body
  );
};

export const Shop = () => {
  const { t } = useI18n();
  const stateUpgrades = useAppSelector(selectUpgrades);
  const resources = useAppSelector(selectResources);
  const upgradeMultipliers = useAppSelector(selectUpgradeMultipliers);
  const multipliers = useAppSelector(selectMultipliers);
  const projectMultiplier = useAppSelector(selectProjectMultiplier);
  const dispatch = useAppDispatch();
  const autoClickPower = useAppSelector(selectAutoClickPower);
  const totalAutoIncome = useAppSelector(selectTotalAutoIncome);
  const total = useAppSelector(selectTotal);
  const totalCPS = autoClickPower + totalAutoIncome;
  
  // Состояние режима покупки
  const [purchaseMode, setPurchaseMode] = useState<PurchaseMode>('x1');
  
  // Состояние тултипа
  const [tooltip, setTooltip] = useState<TooltipData>({
    isVisible: false,
    upgradeId: '',
    position: { x: 0, y: 0 }
  });
  
  // Объединяем данные из стейта с полными данными апгрейдов
  const viewUpgrades = useMemo(() => {
    return UPGRADES.map(originalUpgrade => {
      const stateUpgrade = stateUpgrades.find(u => u.id === originalUpgrade.id);
      const currentLevel = stateUpgrade?.level || 0;

      // Рассчитываем количество и стоимость в зависимости от режима покупки
      let purchaseAmount = 1;
      let purchaseCost = 0;
      
      if (purchaseMode === 'x1') {
        purchaseAmount = 1;
        purchaseCost = calculateUpgradeCost(currentLevel, {
          baseCost: originalUpgrade.cost,
          growthRate: originalUpgrade.growthRate,
          transitionLevel: originalUpgrade.transitionLevel,
          linearIncrement: originalUpgrade.linearIncrement,
        });
      } else if (purchaseMode === 'x10') {
        purchaseAmount = 10;
        purchaseCost = calculateBulkUpgradeCost(
          currentLevel,
          currentLevel + 10,
          originalUpgrade.cost,
          originalUpgrade.growthRate,
          originalUpgrade.transitionLevel,
          originalUpgrade.linearIncrement
        );
      } else if (purchaseMode === 'max') {
        purchaseAmount = calculateMaxAffordableLevels(
          currentLevel,
          resources,
          originalUpgrade.cost,
          originalUpgrade.growthRate,
          originalUpgrade.transitionLevel,
          originalUpgrade.linearIncrement
        );
        if (purchaseAmount > 0) {
          purchaseCost = calculateBulkUpgradeCost(
            currentLevel,
            currentLevel + purchaseAmount,
            originalUpgrade.cost,
            originalUpgrade.growthRate,
            originalUpgrade.transitionLevel,
            originalUpgrade.linearIncrement
          );
        } else {
          // Если нельзя купить ни одного уровня, показываем стоимость первого уровня
          purchaseAmount = 0;
          purchaseCost = calculateUpgradeCost(currentLevel, {
            baseCost: originalUpgrade.cost,
            growthRate: originalUpgrade.growthRate,
            transitionLevel: originalUpgrade.transitionLevel,
            linearIncrement: originalUpgrade.linearIncrement,
          });
        }
      }

      return {
        ...originalUpgrade,
        isVisible: stateUpgrade?.isVisible || false,
        level: currentLevel,
        purchaseAmount,
        cost: purchaseCost,
        // Рассчитываем эффективный CPS с учетом множителей
        effectiveCPS: calculateEffectiveCPS(
          originalUpgrade.CPS,
          originalUpgrade.id,
          originalUpgrade.sphere,
          { multipliers, upgradeMultipliers }
        ),
        totalCPS: calculateTotalUpgradeCPS(
          originalUpgrade.CPS,
          currentLevel,
          originalUpgrade.id,
          originalUpgrade.sphere,
          { multipliers, upgradeMultipliers, projectMultiplier }
        )
      };
    }).filter(upgrade => upgrade.isVisible);
  }, [stateUpgrades, multipliers, upgradeMultipliers, projectMultiplier, purchaseMode, resources]);

  // Обработчики событий мыши для тултипа
  const handleMouseEnter = (upgradeId: string, event: React.MouseEvent) => {
    const rect = event.currentTarget.getBoundingClientRect();
    const tooltipWidth = 280; // Максимальная ширина тултипа
    const tooltipHeight = 150; // Примерная высота тултипа
    
    // Рассчитываем позицию с учетом границ экрана
    let x = rect.right + 10;
    let y = rect.top;
    
    // Проверяем правую границу экрана
    if (x + tooltipWidth > window.innerWidth) {
      x = rect.left - tooltipWidth - 10; // Показываем слева от элемента
    }
    
    // Проверяем нижнюю границу экрана
    if (y + tooltipHeight > window.innerHeight) {
      y = window.innerHeight - tooltipHeight - 20; // Сдвигаем вверх
    }
    
    // Проверяем верхнюю границу экрана
    if (y < 20) {
      y = 20;
    }
    
    setTooltip({
      isVisible: true,
      upgradeId,
      position: { x, y }
    });
  };

  const handleMouseLeave = () => {
    setTooltip(prev => ({ ...prev, isVisible: false }));
  };

  // Обработчик покупки апгрейда
  const handleUpgradePurchase = (upgradeId: string, amount: number) => {
    for (let i = 0; i < amount; i++) {
      dispatch(buyUpgrade(upgradeId));
    }
  };

  // Находим апгрейд для тултипа
  const tooltipUpgrade = viewUpgrades.find(u => u.id === tooltip.upgradeId);
  
  return (
    <div className={styles.shop}>
      {/* Кнопки режимов покупки */}
      {total > 1000 && (
        <div className={styles.purchaseModeButtons}>
          <button
            className={`${styles.purchaseModeBtn} ${purchaseMode === 'x1' ? styles.active : ''}`}
            onClick={() => setPurchaseMode('x1')}
          >
            x1
          </button>
          <button
            className={`${styles.purchaseModeBtn} ${purchaseMode === 'x10' ? styles.active : ''}`}
            onClick={() => setPurchaseMode('x10')}
          >
            x10
          </button>
          <button
            className={`${styles.purchaseModeBtn} ${purchaseMode === 'max' ? styles.active : ''}`}
            onClick={() => setPurchaseMode('max')}
          >
            MAX
          </button>
        </div>
      )}
      
      <div className={styles.shopUpgrades}>
        {viewUpgrades
        .map(upgrade => (
          <div 
            key={upgrade.id}
            onMouseEnter={(e) => handleMouseEnter(upgrade.id, e)}
            onMouseLeave={handleMouseLeave}
          >
            <button 
              onClick={() => handleUpgradePurchase(upgrade.id, upgrade.purchaseAmount)} 
              className={`${styles.upgradeButton} ${resources < upgrade.cost || upgrade.purchaseAmount === 0 ? styles.disabled : ''}`} 
              disabled={resources < upgrade.cost || upgrade.purchaseAmount === 0}
            >
            <UpgradeBackground icon={upgrade.icon} level={upgrade.level} />
            <div className={styles.upgradeContent}>
              <div className={styles.upgradeIconMain}>{upgrade.icon}</div>
              <div className={styles.upgradeInfo}>
                <div className={styles.upgradeName}>
                  {upgrade.name}
                  {purchaseMode === 'x10' && (
                    <span className={styles.purchaseAmount}> x{upgrade.purchaseAmount}</span>
                  )}
                  {purchaseMode === 'max' && upgrade.purchaseAmount > 0 && (
                    <span className={styles.purchaseAmount}> x{upgrade.purchaseAmount}</span>
                  )}
                </div>
                <div className={styles.upgradeDetails}>
                  <span className={styles.upgradeCost}>
                    <CountUp value={Math.round(upgrade.cost)} suffix="₿" duration={300} />
                  </span>
                </div>
              </div>
              {!!upgrade.level && <span className={styles.upgradeLevel}>{upgrade.level}</span>}
            </div>
            
            {/* Прогрессбар для отображения прогресса к покупке */}
            <div className={styles.upgradeProgressBar}>
              <div 
                className={styles.upgradeProgressFill}
                style={{ 
                  width: `${Math.min((resources / upgrade.cost) * 100, 100)}%` 
                }}
              />
            </div>
          </button>
          </div>
        ))}
      </div>
      
      {/* Тултип рендерится через портал в body */}
      <UpgradeTooltip 
        tooltip={tooltip} 
        upgrade={tooltipUpgrade} 
        totalCPS={totalCPS}
      />
    </div>
  );
};
