import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import LanguageDetector from 'i18next-browser-languagedetector';

// Импорт переводов из внешних файлов
import enTranslation from './locales/en/translation.json';
import ruTranslation from './locales/ru/translation.json';
import enQuests from './locales/en/quests.json';
import ruQuests from './locales/ru/quests.json';
import enTalents from './locales/en/talents.json';
import ruTalents from './locales/ru/talents.json';
import enProjects from './locales/en/projects.json';
import ruProjects from './locales/ru/projects.json';
import enNews from './locales/en/news.json';
import ruNews from './locales/ru/news.json';
import enUpgrades from './locales/en/upgrades.json';
import ruUpgrades from './locales/ru/upgrades.json';
import enIntro from './locales/en/intro.json';
import ruIntro from './locales/ru/intro.json';
import enProblems from './locales/en/problems.json';
import ruProblems from './locales/ru/problems.json';

// Ресурсы переводов из внешних файлов
const resources = {
  en: {
    translation: enTranslation,
    quests: enQuests,
    talents: enTalents,
    projects: enProjects,
    news: enNews,
    upgrades: enUpgrades,
    intro: enIntro,
    problems: enProblems
  },
  ru: {
    translation: ruTranslation,
    quests: ruQuests,
    talents: ruTalents,
    projects: ruProjects,
    news: ruNews,
    upgrades: ruUpgrades,
    intro: ruIntro,
    problems: ruProblems
  }
};

i18n
  // Детектор языка браузера
  .use(LanguageDetector)
  // Инициализация react-i18next
  .use(initReactI18next)
  .init({
    resources,
    fallbackLng: 'en', // Базовый язык - английский
    debug: false,
    
    interpolation: {
      escapeValue: false, // React уже делает экранирование
    },
    
    // Настройки детектора языка
    detection: {
      order: ['localStorage', 'navigator', 'htmlTag'],
      lookupLocalStorage: 'i18nextLng',
      caches: ['localStorage'],
    },
    
    // Поддержка множественных форм
    // Для русского языка особые правила
    lng: 'en', // Начальный язык
    
    react: {
      useSuspense: false, // Отключаем Suspense для более простой интеграции
    }
  });

export default i18n;