import React, { useState, useEffect, useCallback, useRef } from 'react';
import styles from './psi.module.scss';
import { useAppDispatch, useAppSelector } from '../../app/hooks';
import { setProjectMultiplier, selectProjectMultiplier } from '../../app/gameSlice';
import { bunch } from '../../utils/debounce';
import { useI18n } from '../../hooks/useI18n';

const DEGRADATION_RATE = 0.01; // Потеря множителя в секунду
const CLICK_POWER = 0.1; // Прирост множителя за клик
const STABLE_DURATIONS = {
  2: 60000, // 1 минута для 2x
  10: 120000, // 2 минуты для 10x
};

export const Psi = () => {
  const dispatch = useAppDispatch();
  const currentProjectMultiplier = useAppSelector(selectProjectMultiplier);
  const { t } = useI18n();
  
  const [multiplier, setMultiplier] = useState(1); // Текущий множитель
  const [stableTimer, setStableTimer] = useState<number | null>(null);
  const [lastStableMultiplier, setLastStableMultiplier] = useState<number | null>(null);
  const [isMouseDown, setIsMouseDown] = useState(false);
  const [autoClickInterval, setAutoClickInterval] = useState(300);
  const [lastSentContribution, setLastSentContribution] = useState(1.0); // Последний отправленный вклад в projectMultiplier
  const intervalRef = useRef<NodeJS.Timeout | null>(null);
  const autoClickRef = useRef<NodeJS.Timeout | null>(null);
  
  // Дебаунсированная функция обновления множителя
  const bunchedUpdateMultiplier = useCallback(
    bunch((newPsiContribution: number) => {
      if (newPsiContribution !== lastSentContribution) {
        const wormholeContribution = lastSentContribution > 0 ? currentProjectMultiplier / lastSentContribution : 1.0;
        const combinedMultiplier = newPsiContribution * wormholeContribution;
        
        dispatch(setProjectMultiplier(Math.max(1.0, combinedMultiplier)));
        setLastSentContribution(newPsiContribution);
      }
    }, 5, 200),
    [dispatch, currentProjectMultiplier, lastSentContribution]
  );
  useEffect(() => {
    bunchedUpdateMultiplier(multiplier);
  }, [multiplier, bunchedUpdateMultiplier]);
  
  // TODO: Добавить селектор таланта для 10x
  // const hasAdvancedTalent = useAppSelector(selectAdvancedPsiTalent);
  const hasAdvancedTalent = true; // Временно true для тестирования
  
  // TODO: Добавить селектор таланта для автоклика
  // const hasAutoClickTalent = useAppSelector(selectAutoClickPsiTalent);
  const hasAutoClickTalent = false; // Временно true для тестирования

  const displayMultiplier = Math.max(1, multiplier); // Минимум 1x


  // Проверка на стабильные множители
  const isStableMultiplier = useCallback((mult: number) => {
    return mult === 2 || (mult === 10 && hasAdvancedTalent);
  }, [hasAdvancedTalent]);

  // Логика деградации - игра всегда активна
  useEffect(() => {
    intervalRef.current = setInterval(() => {
      const now = Date.now();
      
      setMultiplier(prevMult => {
        // Проверяем стабильные множители
        if (isStableMultiplier(prevMult)) {
                     const stableValue = prevMult === 2 ? 2 : 10;
          const stableDuration = STABLE_DURATIONS[stableValue as keyof typeof STABLE_DURATIONS];
          
          if (stableTimer === null || lastStableMultiplier !== stableValue) {
            // Устанавливаем новый таймер для этого множителя
            setStableTimer(now + stableDuration);
            setLastStableMultiplier(stableValue);
            return prevMult; // Держим множитель
          } else if (now < stableTimer) {
            // Всё ещё в стабильном периоде
            return prevMult; // Держим множитель
          } else {
            // Стабильный период закончился - начинаем деградацию
            setStableTimer(null);
            setLastStableMultiplier(null);
            return Math.max(1, prevMult - DEGRADATION_RATE);
          }
        } else {
          // Не стабильный множитель - применяем деградацию
          if (stableTimer !== null) {
            setStableTimer(null);
            setLastStableMultiplier(null);
          }
          return Math.max(1, prevMult - DEGRADATION_RATE);
        }
      });
    }, 100);

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, [stableTimer, lastStableMultiplier, isStableMultiplier]);

  // Логика клика (общая функция)
  const performClick = useCallback(() => {
    
    setMultiplier(prev => {
      const maxMultiplier = hasAdvancedTalent ? 10 : 2;
      const newMultiplier = Math.min(maxMultiplier, prev + CLICK_POWER);
      return newMultiplier;
    });
    
    // Сбрасываем стабильный таймер при активности
    if (stableTimer !== null) {
      setStableTimer(null);
      setLastStableMultiplier(null);
    }
  }, [stableTimer, hasAdvancedTalent]);

  // Обработчик обычного клика
  const handleClick = useCallback(() => {
    if (!isMouseDown) {
      performClick();
    }
  }, [performClick, isMouseDown]);


  // Автоклик при зажатии мыши
  useEffect(() => {
    if (isMouseDown && hasAutoClickTalent) {
      const startAutoClick = () => {
        autoClickRef.current = setTimeout(() => {
          performClick();
          // Ускоряем интервал на 10мс, но не менее 20мс
          setAutoClickInterval(prev => Math.max(20, prev - 10));
          startAutoClick(); // Рекурсивно запускаем следующий клик
        }, autoClickInterval);
      };
      
      startAutoClick();
    } else {
      // Останавливаем автоклик и сбрасываем интервал
      if (autoClickRef.current) {
        clearTimeout(autoClickRef.current);
        autoClickRef.current = null;
      }
      setAutoClickInterval(300); // Сбрасываем интервал к начальному значению
    }

    return () => {
      if (autoClickRef.current) {
        clearTimeout(autoClickRef.current);
        autoClickRef.current = null;
      }
    };
  }, [isMouseDown, hasAutoClickTalent, autoClickInterval, performClick]);

  // Обработчики мыши для автоклика
  const handleMouseDown = useCallback(() => {
    if (hasAutoClickTalent) {
      setIsMouseDown(true);
      performClick(); // Первый клик сразу
    }
  }, [hasAutoClickTalent, performClick]);

  const handleMouseUp = useCallback(() => {
    setIsMouseDown(false);
  }, []);

  const handleMouseLeave = useCallback(() => {
    setIsMouseDown(false);
  }, []);

  // Вычисляем состояния телескопов на основе множителя
  const getTelescopeStates = () => {
    const mult = multiplier;
    
    // Правый телескоп: активен всегда, вращается от 1x до 2x (6 кадров: 0-5)
    const rightProgress = Math.min(Math.max((mult - 1) / 1, 0), 1); // От 1x до 2x (прогресс 0-1)
    const rightFrame = Math.floor(rightProgress * 5.99); // 0-5 кадров (избегаем 6)
    
    // Левый телескоп: активен от 2x до 10x, вращается в обратном порядке (кадры 5-0)
    const leftProgress = hasAdvancedTalent ? Math.min(Math.max((mult - 2) / 8, 0), 1) : 0; // От 2x до 10x (прогресс 0-1)
    const leftFrame = 5 - Math.floor(leftProgress * 5.99); // 5-0 кадров (обратный порядок)
    
    // Лучи правого телескопа: 1-3 уровень во время поворота, 4 уровень при завершении
    let rightBeamPower = 1;
    if(mult >= 10) {
      rightBeamPower = 6;
    } else if (mult >= 2) {
      rightBeamPower = 4; // Завершен поворот
    } else if (mult >= 1) {
      rightBeamPower = Math.min(Math.floor(((mult - 1) / 1) * 3) + 1, 3); // 1-3 уровень
    }
    
    // Лучи левого телескопа: 1-3 уровень во время поворота, потом до 6
    let leftBeamPower = 1;
    if (hasAdvancedTalent && mult >= 2) {
      if (mult >= 10) {
        leftBeamPower = 6; // Завершен поворот до максимума
      } else {
        leftBeamPower = Math.min(Math.floor(((mult - 2) / 8) * 3) + 1, 3); // 1-3 уровень
      }
    }
    
    // Луч центрального телескопа
    let centerBeamPower = 4; // По умолчанию 4
    if (mult >= 2) {
      centerBeamPower = 5; // Когда правый завершен
    }
    if (hasAdvancedTalent && mult >= 10) {
      centerBeamPower = 6; // Когда левый завершен
    }
    
    // Вычисляем углы поворота лучей (в градусах)
    const rightBeamAngle = -rightProgress * 30; // От 0° до 30° для правого
    const leftBeamAngle = leftProgress * 30; // От 0° до -30° для левого (в обратную сторону)
    
    return {
      left: {
        active: hasAdvancedTalent && mult >= 2,
        frame: leftFrame,
        beamPower: leftBeamPower,
        beamAngle: leftBeamAngle
      },
      center: {
        active: true,
        beamPower: centerBeamPower,
        beamAngle: 0
      },
      right: {
        active: true,
        frame: rightFrame,
        beamPower: rightBeamPower,
        beamAngle: rightBeamAngle
      }
    };
  };

  const telescopes = getTelescopeStates();

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <h3 className={styles.title}>{t('projects.psi.title')}</h3>
        <div className={styles.stats}>
          <span>{t('projects.psi.multiplier', { value: displayMultiplier.toFixed(2) })}</span>
        </div>
      </div>

      <div 
        className={styles.gameArea} 
        onClick={handleClick}
        onMouseDown={handleMouseDown}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseLeave}
        style={{ cursor: hasAutoClickTalent ? 'pointer' : 'default' }}
      >
        {/* Фон с землёй и небом */}
        <div className={styles.background}>
          {/* TODO: Заменить на изображение изгиба земли с облаками */}
          <div className={styles.sky}></div>
          <div className={styles.ground}></div>
        </div>

        {/* Телескопы */}
        <div className={styles.telescopes}>
          {/* Левый телескоп */}
          <div 
            className={`${styles.telescope} ${styles.left}`}
            style={{ 
              backgroundPositionY: `-${telescopes.left.frame * 102}px`,
              opacity: telescopes.left.active ? 1 : 0.3
            }}
          >
            {/* TODO: Заменить на спрайт левого телескопа */}
            
            {telescopes.left.active && (
              <div 
                className={`${styles.beam} ${styles['beamLevel' + telescopes.left.beamPower]}`}
                style={{
                  transform: `translateX(-50%) rotate(${telescopes.left.beamAngle}deg)`,
                  transformOrigin: '50% 170px' // 150px высота луча + 20px = 170px
                }}
              >
                {/* Луч левого телескопа */}
              </div>
            )}
          </div>

          {/* Центральный телескоп */}
          <div className={`${styles.telescope} ${styles.center}`}>
            
            <div 
              className={`${styles.beam} ${styles['beamLevel' + telescopes.center.beamPower]}`}
              style={{
                transform: `translateX(-50%) rotate(${telescopes.center.beamAngle}deg)`,
                transformOrigin: '50% 170px'
              }}
            >
              {/* Луч центрального телескопа */}
            </div>
          </div>

          {/* Правый телескоп */}
          <div 
            className={`${styles.telescope} ${styles.right}`}
            style={{ 
              backgroundPositionY: `-${telescopes.right.frame * 102}px`,
            }}
          >
            
            {telescopes.right.active && (
              <div 
                className={`${styles.beam} ${styles['beamLevel' + telescopes.right.beamPower]}`}
                style={{
                  transform: `translateX(-50%) rotate(${telescopes.right.beamAngle}deg)`,
                  transformOrigin: '50% 170px'
                }}
              >
                {/* Луч правого телескопа */}
              </div>
            )}
          </div>
        </div>

        {/* График множителя */}
        <div className={styles.levelBar}>
          <div className={styles.levelLabels}>
            <div className={styles.levelMark} style={{ left: '0%', color: '#ffaa44' }}>1x</div>
            <div className={styles.levelMark} style={{ left: '100%', color: hasAdvancedTalent ? '#4444ff' : '#44ff44' }}>
              {hasAdvancedTalent ? '10x' : '2x'}
            </div>
          </div>
          <div 
            className={styles.levelFill}
            style={{ 
              width: `${Math.min((displayMultiplier / (hasAdvancedTalent ? 10 : 2)) * 100, 100)}%`,
              backgroundColor: hasAdvancedTalent && displayMultiplier >= 10 ? '#4444ff' : displayMultiplier >= 2 ? '#44ff44' : '#ffaa44'
            }}
          />
        </div>
      </div>
    </div>
  );
};