import React from 'react';
import classNames from 'classnames';
import { ExtendedMiniGame } from '../../MiniGames';
import { useAppSelector } from '../../app/hooks';
import { selectGame } from '../../app/gameSlice';
import styles from './RoomButton.module.scss';

interface RoomButtonProps {
  game: ExtendedMiniGame;
  isAvailable: boolean;
  cooldown: number | null;
  onGameStart: (game: ExtendedMiniGame) => void;
  roomClipPath: string; // CSS clip-path для обрезки области комнаты
}

const RoomButton: React.FC<RoomButtonProps> = ({
  game,
  isAvailable,
  cooldown,
  onGameStart,
  roomClipPath
}) => {
  const gameState = useAppSelector(selectGame);
  
  const handleClick = () => {
    if (isAvailable && !cooldown) {
      onGameStart(game);
    }
  };

  // Проверяем активен ли эффект от этой игры
  const activeEffect = gameState.miniGamesState[game.id];
  const hasActiveBonus = activeEffect && activeEffect.endTime > Date.now();

  const getRoomTypeClass = () => {
    switch (game.resourceEffect.type) {
      case 'shield':
      case 'economy':
        return styles.engineRoom;
      case 'science':
        return styles.researchRoom;
      case 'faith':
        return styles.defenseRoom;
      case 'global':
        return styles.bridgeRoom;
      default:
        return styles.engineRoom;
    }
  };

  return (
    <div
      className={classNames(styles.roomButton, getRoomTypeClass(), {
        [styles.available]: isAvailable && !cooldown,
        [styles.cooldown]: !!cooldown,
        [styles.locked]: !isAvailable
      })}
      style={{
        left: `${game.sectionPosition.x}%`,
        top: `${game.sectionPosition.y}%`,
        clipPath: roomClipPath
      }}
      onClick={handleClick}
      title={`${game.name} - ${game.description}`}
    >
      {/* Индикатор статуса над комнатой */}
      <div className={styles.statusIndicator}>
        {/* Активный бонус */}
        {hasActiveBonus && (
          <div className={styles.activeBonusIndicator}>
            <div className={styles.bonusIcon}>🌟</div>
            <div className={styles.bonusInfo}>
              <div className={styles.bonusType}>
                {game.resourceEffect.type === 'global' ? 'Все' : 
                  game.resourceEffect.type === 'economy' ? 'Эко' :
                  game.resourceEffect.type === 'science' ? 'Наука' : 
                  game.resourceEffect.type === 'faith' ? 'Вера' : 'Щиты'}
              </div>
              <div className={styles.bonusMultiplier}>
                {activeEffect?.multiplier > 1 
                  ? `+${((activeEffect.multiplier - 1) * 100).toFixed(0)}%`
                  : `${((activeEffect.multiplier - 1) * 100).toFixed(0)}%`}
              </div>
            </div>
          </div>
        )}
        
        {/* Кулдаун */}
        {cooldown && (
          <div className={styles.cooldownTimer}>
            {Math.ceil(cooldown)}s
          </div>
        )}
        
        {/* Готово к использованию */}
        {isAvailable && !cooldown && !hasActiveBonus && (
          <div className={styles.readyIndicator}>
            ⚡
          </div>
        )}
        
        {/* Заблокировано */}
        {!isAvailable && (
          <div className={styles.lockedIndicator}>
            🔒
          </div>
        )}
      </div>

      {/* Эффект подсветки комнаты */}
      <div className={styles.roomHighlight} />
    </div>
  );
};

export default RoomButton;