import React, { useState, useEffect, useRef, useCallback } from 'react';
import debounce from 'lodash/debounce';
import { useAppDispatch, useAppSelector } from '../../app/hooks';
import { selectGame, setFTLResourceAllocation, startFTLJump, completeFTLJump } from '../../app/gameSlice';
import styles from './index.module.scss';
import classNames from 'classnames';
import FTLjump from './FTLjump';

const FTLNavigation: React.FC = () => {
  const dispatch = useAppDispatch();
  const game = useAppSelector(selectGame);
  
  const { ftlSystem } = game;
  const { energyAccumulated, energyRequired, isJumping, jumpStartTime, resourceAllocation } = ftlSystem;
  
  // Локальное состояние для слайдера с дебаунсом
  const [localAllocation, setLocalAllocation] = useState(resourceAllocation);
  const [animationAllocation, setAnimationAllocation] = useState(resourceAllocation);
  
  // Состояние для позиции фона
  const animationRef = useRef<number>(0);
  const progressBarRef = useRef<HTMLDivElement>(null);
  
  // Управление анимацией фона
  useEffect(() => {
    let animationFrameId: number;
    let lastTime = performance.now();
    
    const animate = (currentTime: number) => {
      const deltaTime = currentTime - lastTime;
      lastTime = currentTime;
      
      // Скорость анимации зависит от localAllocation
      const speed = Math.min(1000, Math.max(1, (100 / animationAllocation) * 1));
      const increment = (300 / (speed * 1000)) * deltaTime; // 300% за полный цикл анимации
      
      animationRef.current += increment;
      
      // Сброс позиции когда достигаем конца
      if (animationRef.current > 250) {
        animationRef.current = -50;
      }
      
      // Применяем позицию к элементу
      if (progressBarRef.current) {
        progressBarRef.current.style.setProperty('--bg-position', `${animationRef.current}%`);
      }
      if(animationAllocation === 0){
        progressBarRef.current?.style.setProperty('opacity', '0');
      } else {
        progressBarRef.current?.style.setProperty('opacity', '1');
      }
      
      animationFrameId = requestAnimationFrame(animate);
    };
    
    animationFrameId = requestAnimationFrame(animate);
    
    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, [animationAllocation]);

  const debounceAllocation = useCallback(debounce((value: number) => {
    dispatch(setFTLResourceAllocation(value));
    setAnimationAllocation(value);
  }, 150), [dispatch]);
  
  const handleSliderChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = parseInt(e.target.value);
    debounceAllocation(value);
    setLocalAllocation(value);
  };
  
  const handleJump = () => {
    if (energyAccumulated >= energyRequired && !isJumping) {
      dispatch(startFTLJump());
      
      // Завершаем прыжок через 40 секунд
      setTimeout(() => {
        dispatch(completeFTLJump());
      }, 40000);
    }
  };
  
  const progressPercentage = Math.min((energyAccumulated / energyRequired) * 100, 100);
  const canJump = energyAccumulated >= energyRequired && !isJumping;
  
  // Показываем анимацию прыжка
  if (isJumping) {
    
    return (
      <FTLjump />
    );
  }
  
  return (
    <div className={styles.ftlContainer}>
      {canJump ? (
          <button 
            className={styles.jumpButton}
            onClick={handleJump}
          >
            ПРЫЖОК
          </button>
        ) : (
          <>
            <div className={styles.progressContainer}>
              <div className={styles.progressBarContainer}>
                <h4>Заряд FTL системы</h4>  
                <div className={styles.progressBar} >
                  <div className={styles.progressBarBackground} ref={progressBarRef}></div>
                
                <div 
                  className={classNames(styles.progressFill, { [styles.ready]: canJump })}
                  style={{ width: `${progressPercentage}%` }}
                >
                  
                  </div>
                </div>
              </div>
              
              
              
            </div>
            
            <div className={styles.controls}>
              <label className={styles.sliderLabel}>
                Сила заряда: {localAllocation}%
              </label>
              <input
                type="range"
                min="0"
                max="100"
                value={localAllocation}
                onChange={handleSliderChange}
                className={styles.slider}
              />
            </div>
          </>
      )}
    </div>
  );
};

export default FTLNavigation; 