import React, { useState, useEffect } from 'react';
import { useAppDispatch, useAppSelector } from '../../app/hooks';
import { selectConqueredCountries, setStage } from '../../app/gameSlice';

interface LaunchPadProps {
  x: number;
  y: number;
}

export const LaunchPad: React.FC<LaunchPadProps> = ({ x, y }) => {
  const dispatch = useAppDispatch();
  const conqueredCountries = useAppSelector(selectConqueredCountries);
  
  // Состояние для отслеживания прогресса анимации каждого элемента (0-1)
  const [animationProgress, setAnimationProgress] = useState<{
    base: number;
    bottom: number;
    top: number;
  }>({
    base: 0,
    bottom: 0,
    top: 0,
  });
  
  // Определяем стадию ракеты по количеству захваченных стран
  const getStage = () => {
    const count = conqueredCountries.length;
    if (count >= 150) return 3;
    if (count >= 100) return 2;
    if (count >= 50) return 1;
    return 0; // Не показываем ракету
  };
  
  const stage = getStage();
  
  // Эффект для запуска анимации элементов
  useEffect(() => {
    const animateElement = (elementId: 'base' | 'bottom' | 'top') => {
      const startTime = Date.now();
      const duration = 60000; // 60 секунд
      
      const animate = () => {
        const elapsed = Date.now() - startTime;
        const progress = Math.min(elapsed / duration, 1);
        
        setAnimationProgress(prev => ({
          ...prev,
          [elementId]: progress,
        }));
        
        if (progress < 1) {
          requestAnimationFrame(animate);
        }
      };
      
      requestAnimationFrame(animate);
    };
    
    // Запускаем анимацию для base при stage >= 1
    if (stage >= 1 && animationProgress.base === 0) {
      animateElement('base');
    }
    
    // Запускаем анимацию для bottom при stage >= 2
    if (stage >= 2 && animationProgress.bottom === 0) {
      setTimeout(() => animateElement('bottom'), 0);
    }
    
    // Запускаем анимацию для top при stage >= 3
    if (stage >= 3 && animationProgress.top === 0) {
      setTimeout(() => animateElement('top'), 0);
    }
  }, [stage, animationProgress.base, animationProgress.bottom, animationProgress.top]);
  
  // Если не достигли 50 стран, не показываем ракету
  //if (stage === 0) return null;
  
  const offsetX = 30;
  const offsetY = -20;
  const size = 60;
  
  const handleClick = () => {
    if (stage === 3) {
      // Запуск процесса перехода во вторую стадию
      dispatch(setStage(2));
    }
  };
  
  // Определяем какие элементы показывать для каждой стадии
  const getVisibleElements = () => {
    const elements = [];
    
    // Первый элемент (основа) - показывается всегда с 1 стадии
    if (stage >= 1) {
      elements.push({
        id: 'base',
        spriteX: 0,
        spriteY: 0,
        spriteWidth: 840,
        spriteHeight: 936,
        scale: 0.1, // Масштаб для отображения
        offsetX: 0,
        offsetY: 0,
        progress: animationProgress.base,
      });
    }
    
    // Второй элемент (правый нижний) - добавляется со 2 стадии
    if (stage >= 2) {
      elements.push({
        id: 'bottom',
        spriteX: 840,
        spriteY: 470, // нижняя часть правого блока
        spriteWidth: 350,
        spriteHeight: 432,
        scale: 0.1,
        offsetX: -15, // Сдвигаем правее
        offsetY: 12,   // Немного вниз
        progress: animationProgress.bottom,
      });
    }
    
    // Третий элемент (правый верхний) - добавляется с 3 стадии
    if (stage >= 3) {
      elements.push({
        id: 'top',
        spriteX: 840,
        spriteY: 0, // верхняя часть правого блока
        spriteWidth: 350,
        spriteHeight: 470,
        scale: 0.1,
        offsetX: -15, // Сдвигаем правее (выравниваем с вторым)
        offsetY: -23, // Опускаем на 10 пикселей ниже (было -40, стало -30)
        progress: animationProgress.top,
      });
    }
    
    return elements;
  };
  
  const visibleElements = getVisibleElements();
  
  // Если нет элементов для отображения
  if (visibleElements.length === 0) return null;

  return (
    <g
      style={{
        pointerEvents: stage === 3 ? 'auto' : 'none',
        cursor: stage === 3 ? 'pointer' : 'default',
      }}
      onClick={stage === 3 ? handleClick : undefined}
    >
      <defs>
        {/* Фильтр для свечения на 3 стадии */}
        {stage === 3 && (
          <filter id="glowEffect">
            <feGaussianBlur stdDeviation="3" result="coloredBlur"/>
            <feMerge> 
              <feMergeNode in="coloredBlur"/>
              <feMergeNode in="SourceGraphic"/>
            </feMerge>
          </filter>
        )}
      </defs>
      
      {/* Рендерим все видимые элементы */}
      {visibleElements.map((element) => {
        const elementWidth = element.spriteWidth * element.scale;
        const elementHeight = element.spriteHeight * element.scale;
        
        // Вычисляем высоту для анимации снизу-вверх
        const animatedHeight = elementHeight * element.progress;
        
        return (
          <g key={element.id}>
            {/* Clip path для обрезки спрайта с анимацией */}
            <defs>
              <clipPath id={`clip-${element.id}-${stage}`}>
                <rect
                  x={x + offsetX - elementWidth / 2 + element.offsetX}
                  y={y + offsetY - elementHeight / 2 + element.offsetY + (elementHeight - animatedHeight)}
                  width={elementWidth}
                  height={animatedHeight}
                />
              </clipPath>
            </defs>
            
            {/* Элемент sprite map */}
            <image
              x={x + offsetX - elementWidth / 2 - (element.spriteX * element.scale) + element.offsetX}
              y={y + offsetY - elementHeight / 2 - (element.spriteY * element.scale) + element.offsetY}
              width={1190 * element.scale} // общая ширина sprite map
              height={936 * element.scale} // общая высота sprite map
              href={`${process.env.PUBLIC_URL}/assets/startRocket.png`}
              clipPath={`url(#clip-${element.id}-${stage})`}
              opacity={stage === 3 ? 1 : 0.9}
              style={{
                filter: stage === 3 ? 'url(#glowEffect)' : 'none',
              }}
            />
          </g>
        );
      })}
      
      {/* Hover обводка для 3 стадии
      {stage === 3 && (
        <circle
          cx={x + offsetX}
          cy={y + offsetY}
          r={40} // Примерный радиус обводки
          fill="none"
          stroke="#00ff00"
          strokeWidth="3"
          opacity="0"
          style={{
            pointerEvents: 'none',
          }}
        >
          <animate
            attributeName="opacity"
            values="0;1;0"
            dur="2s"
            repeatCount="indefinite"
          />
        </circle>
      )} */}
    </g>
  );
}; 