import React, { RefObject } from 'react';
import styles from './index.module.scss';
import { Talent } from '../../types';
import { TALENTS } from '../../Talents';
import { ECONOMY, SCIENCE, FAITH } from '../../app/constants';
import { getEffectsDescription } from '../../app/utils';
import { getProjectFromTalent } from '../../Projects';
import { useDevTools } from '../../parts/DevTools';
import { useI18n } from '../../hooks/useI18n';

// Получение категории таланта для тултипа
const getCategoryClass = (category: string): string => {
  if (category === ECONOMY) return styles.economy;
  if (category === SCIENCE) return styles.science;
  if (category === FAITH) return styles.faith;
  return '';
};

// Функция-адаптер для совместимости с предыдущим кодом
export const getTalentEffects = (talent: Talent, t?: any): string[] => {
  // Сначала пытаемся получить перевод из файла локализации
  if (t) {
    const translatedEffect = t(`talents:${talent.id}.effectDescription`, { defaultValue: null });
    // Проверяем, что мы получили реальный перевод, а не ключ
    if (translatedEffect && translatedEffect !== `talents:${talent.id}.effectDescription`) {
      return [translatedEffect];
    }
  }
  
  if (talent.meta?.effectDesctription) {
    return [talent.meta.effectDesctription];
  }
  return getEffectsDescription(talent.effects);
};

// Получение требований таланта
const getTalentRequirements = (talent: Talent, t: any): string[] => {
  // Сначала пытаемся получить перевод из файла локализации
  const translatedRequirements = t(`talents:${talent.id}.requirementsDescription`, { defaultValue: null });
  // Проверяем, что мы получили реальный перевод, а не ключ
  if (translatedRequirements && translatedRequirements !== `talents:${talent.id}.requirementsDescription`) {
    return [translatedRequirements];
  }
  
  if (talent.meta?.requirementsDescription) {
    return [talent.meta.requirementsDescription];
  }
  const requirements: string[] = [];
  
  // Проверяем, есть ли зависимости от других талантов
  if (talent.requires.length > 0) {
    talent.requires.forEach(requirement => {
      if (requirement.talentId) {
        const requiredTalent = TALENTS.find(tal => tal.id === requirement.talentId);
        if (requiredTalent) {
          requirements.push(t('talents.required_talent', { talent: requiredTalent.name }));
        }
      }
    });
  }
  
  // Проверяем доступность на основе ресурсов
  const availabilityString = talent.available.map(fn => fn.toString()).join(' ');
  
  // Проверка ресурсов экономики
  const economyMatch = availabilityString.match(/ECONOMY.+?>=\s*([\d.]+)/);
  if (economyMatch) {
    const resources = parseFloat(economyMatch[1]);
    requirements.push(t('talents.resource_requirements.economy_resources', { resources: `<span class="economy-req">${resources}</span>` }));
  }
  
  // Проверка ресурсов науки
  const scienceMatch = availabilityString.match(/SCIENCE.+?>=\s*([\d.]+)/);
  if (scienceMatch) {
    const resources = parseFloat(scienceMatch[1]);
    requirements.push(t('talents.resource_requirements.science_resources', { resources: `<span class="science-req">${resources}</span>` }));
  }
  
  // Проверка ресурсов веры
  const faithMatch = availabilityString.match(/FAITH.+?>=\s*([\d.]+)/);
  if (faithMatch) {
    const resources = parseFloat(faithMatch[1]);
    requirements.push(t('talents.resource_requirements.faith_resources', { resources: `<span class="faith-req">${resources}</span>` }));
  }
  
  // Проверка общих ресурсов
  const resourcesMatch = availabilityString.match(/resources\s*>=\s*([\d.]+)/);
  if (resourcesMatch) {
    const resources = parseFloat(resourcesMatch[1]);
    requirements.push(t('talents.resource_requirements.general_resources', { resources: `<span class="resource-req">${resources}</span>` }));
  }
  
  return requirements;
};

// Отдельный компонент для информации о проекте
const ProjectTooltip: React.FC<{
  projectKey: string;
  projectName: string;
  projectDescription: string;
  projectImage: string;
}> = ({ projectKey, projectName, projectDescription, projectImage }) => {
  const { t } = useI18n();
  
  return (
    <div className={styles.projectTooltip}>
      <div className={styles.projectHeader}>
        <img 
          src={projectImage} 
          alt={projectName} 
          className={styles.projectJumbo}
        />
      </div>
      <div className={styles.projectName}>{t(`projects:${projectKey}.name`, { defaultValue: projectName })}</div>
      <div className={styles.projectDescription}>{t(`projects:${projectKey}.description`, { defaultValue: projectDescription })}</div>
    </div>
  );
};

interface TalentTooltipProps {
  talent: Talent;
  position: { x: number; y: number };
  boundaryAdjustment: 'left' | 'right' | 'center';
  tooltipRef?: RefObject<HTMLDivElement | null>;
  showDevInfo?: boolean; // Показывать ли информацию для разработчиков
}

const TalentTooltip: React.FC<TalentTooltipProps> = ({ 
  talent, 
  position, 
  boundaryAdjustment,
  tooltipRef,
  showDevInfo = false
}) => {
  const { showAllTalents } = useDevTools();
  const { t } = useI18n();
  
  // Получаем переводы для таланта
  const talentName = t(`talents:${talent.id}.name`, { defaultValue: talent.name });
  const talentDescription = t(`talents:${talent.id}.description`, { defaultValue: talent.description });
  
  // Получаем списки эффектов и требований
  const effects = getTalentEffects(talent, t);
  const requirements = getTalentRequirements(talent, t);
  
  // Проверяем, запускает ли талант проект
  const project = getProjectFromTalent(talent);
  
  return (
    <div 
      className={styles.tooltipContainer}
      style={{
        left: `${position.x}px`, 
        top: `${position.y}px` 
      }}
    >
      <div
        ref={tooltipRef}
        className={`${styles.talentTooltip} ${styles[`tooltip-${boundaryAdjustment}`]}`}
      >
        <div className={styles.tooltipHeaderWow}>
          <div className={`${styles.tooltipIcon} ${getCategoryClass(talent.category)}`}>
            {talent.icon.length > 10 ? <img width={32} height={32} src={talent.icon} alt={talent.name} /> : talent.icon}
          </div>
          <div className={styles.tooltipTitleContainer}>
            <div className={styles.tooltipName}>{talentName}</div>
            <div className={`${styles.tooltipCategory} ${getCategoryClass(talent.category)}`}>
              {talent.category}
            </div>
          </div>
        </div>
        
        <div 
          className={styles.tooltipDescription}
          dangerouslySetInnerHTML={{ __html: talentDescription || t('talents.no_description') }}
        />
        
        {effects.length > 0 && (
          <div className={styles.tooltipEffects}>
            <div className={styles.tooltipSectionTitle}>{t('talents.effects')}</div>
            <ul className={styles.effectsList}>
              {effects.map((effect, index) => (
                <li key={index} className={styles.effectItem} dangerouslySetInnerHTML={{ __html: effect }} />
              ))}
            </ul>
          </div>
        )}
        
        {/* Отображаем статус таланта */}
        <div className={styles.tooltipStatus}>
          {talent.state === 'active' ? (
            <span className={styles.activeStatus}>{t('talents.status.active')}</span>
          ) : talent.isAvailable ? (
            <span className={styles.availableStatus}>{t('talents.status.available')}</span>
          ) : (
            <div className={styles.tooltipRequirements}>
              <div className={styles.tooltipSectionTitle}>{t('talents.requirements')}</div>
              {requirements.length > 0 ? (
                <ul className={styles.requirementsList}>
                  {requirements.map((req, index) => (
                    <li key={index} className={styles.lockedStatus} dangerouslySetInnerHTML={{ __html: req }} />
                  ))}
                </ul>
              ) : (
                <span className={styles.lockedStatus}>
                  {t('talents.status.locked')}
                </span>
              )}
              {talent.requires.length > 0 && (
                <ul className={styles.requirementsList}>
                  {talent.requires.map((req, index) => (
                    <li key={index} className={styles.lockedStatus}>
                      {t('talents.status.talent_required', { talent: TALENTS.find(t => t.id === req.talentId)?.name })}
                    </li>                  
                  ))}
                </ul>
              )}
            </div>
          )}
        </div>
        
        {/* Информация для разработчиков */}
        {showDevInfo && showAllTalents && (
          <div className={styles.tooltipDevInfo}>
            <div className={styles.tooltipSectionTitle}>Dev Info:</div>
            <div className={styles.devInfoItem}>
              Позиция: [{talent.position[0]}, {talent.position[1]}]
            </div>
            <div className={styles.devInfoItem}>
              ID: {talent.id}
            </div>
            <div className={styles.devInfoItem}>
              Стоимость: {talent.cost}
            </div>
          </div>
        )}
        
        {talent.meta?.flavorText && (
          <div className={styles.tooltipFlavorText}>
            {talent.meta.flavorText}
          </div>
        )}
      </div>
      
      {/* Отдельный блок для проекта */}
      {project && (
        <ProjectTooltip
          projectKey={project.key}
          projectName={project.name}
          projectDescription={project.description}
          projectImage={project.image}
        />
      )}
    </div>
  );
};

export default TalentTooltip; 