import React, { useState, useEffect } from 'react';
import styles from './index.module.scss';
import { useAppSelector } from '../../app/hooks';
import { selectActiveNews } from '../../app/gameSlice';
import { News } from '../../News';
import classNames from 'classnames';
import { useI18n } from '../../hooks/useI18n';

const NewsMarquee: React.FC = () => {
  const activeNewsId = useAppSelector(selectActiveNews);
  const [currentNews, setCurrentNews] = useState<{ text: string; isSpecial: boolean } | null>(null);
  const { t } = useI18n();

  const getNewsText = (newsId: string) => {
    if (!newsId) return '';
    const newsItem = News[newsId];
    return newsItem ? t(`news:${newsId}`, { defaultValue: newsItem.text }) : '';
  };

  const isSpecialNews = (newsId: string) => {
    if (!newsId) return false;
    const newsItem = News[newsId];
    return newsItem ? newsItem.stage === 'special' : false;
  };

  const formatNewsText = (text: string, isSpecial: boolean) => {
    if (isSpecial) {
      return `⚡ ${text} ⚡`;
    }
    return text;
  };

  useEffect(() => {
    if (activeNewsId) {
      const newsText = getNewsText(activeNewsId);
      const isSpecial = isSpecialNews(activeNewsId);
      const formattedText = formatNewsText(newsText, isSpecial);
      
      setCurrentNews({
        text: formattedText,
        isSpecial
      });
    }
  }, [activeNewsId]);

  if (!currentNews || !currentNews.text) {
    return null;
  }

  return (
    <div className={classNames(styles.newsMarquee, { [styles.special]: currentNews.isSpecial })}>
      {currentNews.isSpecial && (
        <div className={styles.lightningBackground}>
          <div className={styles.lightning}></div>
          <div className={styles.lightning}></div>
          <div className={styles.lightning}></div>
        </div>
      )}
      
      <div className={styles.marqueeContainer}>
        <div className={styles.marqueeContent}>
          {currentNews.text}
        </div>
      </div>
    </div>
  );
};

export default NewsMarquee; 