import React, { useState } from 'react';
import { useAppDispatch, useAppSelector } from '../../app/hooks';
import {
  selectMasterVolume,
  selectMusicVolume,
  selectEffectsVolume,
  selectIsMuted,
  selectIsMusicMuted,
  selectIsEffectsMuted,
  setMasterVolume,
  setMusicVolume,
  setEffectsVolume,
  toggleMute,
  toggleMusicMute,
  toggleEffectsMute,
} from '../../app/soundSlice';
import { useSoundIntegration } from '../../hooks/useSoundIntegration';
import { useI18n } from '../../hooks/useI18n';
import { useTranslation } from 'react-i18next';
import styles from './SettingsMenu.module.scss';

export const SettingsMenu: React.FC = () => {
  const dispatch = useAppDispatch();
  const [isOpen, setIsOpen] = useState(false);
  const { playButtonSound } = useSoundIntegration();
  const { t } = useI18n();
  const { i18n } = useTranslation();
  
  const masterVolume = useAppSelector(selectMasterVolume);
  const musicVolume = useAppSelector(selectMusicVolume);
  const effectsVolume = useAppSelector(selectEffectsVolume);
  const isMuted = useAppSelector(selectIsMuted);
  const isMusicMuted = useAppSelector(selectIsMusicMuted);
  const isEffectsMuted = useAppSelector(selectIsEffectsMuted);

  const languages = [
    { code: 'en', name: 'English', flag: '🇬🇧' },
    { code: 'ru', name: 'Русский', flag: '🇷🇺' }
  ];

  const handleMasterVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    dispatch(setMasterVolume(parseFloat(e.target.value)));
  };

  const handleMusicVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    dispatch(setMusicVolume(parseFloat(e.target.value)));
  };

  const handleEffectsVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    dispatch(setEffectsVolume(parseFloat(e.target.value)));
  };

  const handleToggleMenu = () => {
    playButtonSound();
    setIsOpen(!isOpen);
  };

  const handleToggleMute = () => {
    playButtonSound();
    dispatch(toggleMute());
  };

  const handleToggleMusicMute = () => {
    playButtonSound();
    dispatch(toggleMusicMute());
  };

  const handleToggleEffectsMute = () => {
    playButtonSound();
    dispatch(toggleEffectsMute());
  };

  const handleLanguageChange = (languageCode: string) => {
    playButtonSound();
    i18n.changeLanguage(languageCode);
  };

  return (
    <div className={styles.settingsMenu}>
      <button 
        className={styles.menuButton}
        onClick={handleToggleMenu}
        title={t('settings.tooltips.menu')}
      >
        ☰
      </button>
      
      {isOpen && (
        <div className={styles.dropdown}>
          <div className={styles.header}>
            <h3>{t('settings.title')}</h3>
            <button 
              className={styles.closeButton}
              onClick={handleToggleMenu}
            >
              ✕
            </button>
          </div>
          
          <div className={styles.content}>
            {/* Языковые настройки */}
            <div className={styles.section}>
              <h4>{t('settings.language')}</h4>
              <div className={styles.languageButtons}>
                {languages.map((lang) => (
                  <button
                    key={lang.code}
                    onClick={() => handleLanguageChange(lang.code)}
                    className={`${styles.languageButton} ${
                      i18n.language === lang.code ? styles.active : ''
                    }`}
                    title={lang.name}
                  >
                    <span className={styles.flag}>{lang.flag}</span>
                    <span className={styles.code}>{lang.code.toUpperCase()}</span>
                  </button>
                ))}
              </div>
            </div>

            {/* Звуковые настройки */}
            <div className={styles.section}>
              <h4>{t('settings.sound')}</h4>
              
              {/* Общая громкость */}
              <div className={styles.volumeControl}>
                <label>{t('sound.master_volume')}</label>
                <div className={styles.sliderContainer}>
                  <input
                    type="range"
                    min="0"
                    max="1"
                    step="0.01"
                    value={masterVolume}
                    onChange={handleMasterVolumeChange}
                    className={styles.volumeSlider}
                  />
                  <span className={styles.volumeValue}>
                    {Math.round(masterVolume * 100)}%
                  </span>
                  <button 
                    className={`${styles.muteButton} ${isMuted ? styles.muted : ''}`}
                    onClick={handleToggleMute}
                    title={isMuted ? t('sound.tooltips.unmute') : t('sound.tooltips.mute')}
                  >
                    {isMuted ? '🔇' : '🔊'}
                  </button>
                </div>
              </div>

              {/* Музыка */}
              <div className={styles.volumeControl}>
                <label>{t('sound.music')}</label>
                <div className={styles.sliderContainer}>
                  <input
                    type="range"
                    min="0"
                    max="1"
                    step="0.01"
                    value={musicVolume}
                    onChange={handleMusicVolumeChange}
                    className={styles.volumeSlider}
                    disabled={isMusicMuted}
                  />
                  <span className={styles.volumeValue}>
                    {Math.round(musicVolume * 100)}%
                  </span>
                  <button 
                    className={`${styles.muteButton} ${isMusicMuted ? styles.muted : ''}`}
                    onClick={handleToggleMusicMute}
                    title={isMusicMuted ? t('sound.tooltips.unmute_music') : t('sound.tooltips.mute_music')}
                  >
                    {isMusicMuted ? '🔇' : '🎵'}
                  </button>
                </div>
              </div>

              {/* Эффекты */}
              <div className={styles.volumeControl}>
                <label>{t('sound.effects')}</label>
                <div className={styles.sliderContainer}>
                  <input
                    type="range"
                    min="0"
                    max="1"
                    step="0.01"
                    value={effectsVolume}
                    onChange={handleEffectsVolumeChange}
                    className={styles.volumeSlider}
                    disabled={isEffectsMuted}
                  />
                  <span className={styles.volumeValue}>
                    {Math.round(effectsVolume * 100)}%
                  </span>
                  <button 
                    className={`${styles.muteButton} ${isEffectsMuted ? styles.muted : ''}`}
                    onClick={handleToggleEffectsMute}
                    title={isEffectsMuted ? t('sound.tooltips.unmute_effects') : t('sound.tooltips.mute_effects')}
                  >
                    {isEffectsMuted ? '🔇' : '🔔'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
