import React from "react";
import styles from './collider.module.scss';
import { useAppSelector } from "../../app/hooks";
import { selectSecondStage } from "../../app/gameSlice";
import { MATERIALS } from "../../constants";
import gravitino from '../../assets/pre/gravitino.jpg';
import neutronium from '../../assets/pre/neutronium.webp';
import { useI18n } from "../../hooks/useI18n";

export const Collider = () => {
  const secondStage = useAppSelector(selectSecondStage);
  const material = secondStage.filter((material) => MATERIALS.includes(material))[0];
  const { t } = useI18n();
  
  const getMaterialName = (material: string): string => {
    switch (material) {
      case 'gravitino':
        return 'Gravitino';
      case 'neutronium':
        return 'Neutronium';
      default:
        return t('projects.collider.none');
    }
  };
  
  const renderMaterial = () => {
  switch (material) {
    case 'gravitino':
        return (
          <div className={styles.materialContainer}>
            <div className={styles.materialImageContainer}>
              <h3 className={styles.title}>{t('projects.collider.discovered', { material: <span className={styles.materialName}>Gravitino</span> })}</h3>
              <img src={gravitino} alt="gravitino" className={styles.materialImage} />
            </div>
            <h4>{t('projects.collider.new_possibilities')}</h4>
          </div>
        );
    case 'neutronium':
        return (
          <div className={styles.materialContainer}>
            <div className={styles.materialImageContainer}>
              <h3 className={styles.title}>{t('projects.collider.discovered', { material: <span className={styles.materialName}>Neutronium</span> })}</h3>
              <img src={neutronium} alt="neutronium" className={styles.materialImage} />
            </div>
            <h4>{t('projects.collider.new_possibilities')}</h4>
          </div>
        );
    default:
        return <div className={styles.noMaterial}>{t('projects.collider.no_material')}</div>;
  }
  };

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <h3 className={styles.title}>{t('projects.collider.title')}</h3>
        <div className={styles.stats}>
          <span>{t('projects.collider.material', { material: getMaterialName(material) })}</span>
        </div>
      </div>
      
      <div className={styles.gameArea}>
        {renderMaterial()}
      </div>
    </div>
  );
};
