import React, { useState, useEffect, useRef } from 'react';
import styles from './index.module.scss';
import classNames from 'classnames';
import ShipManager from './ShipManager';
import FTLNavigation from '../../../components/FTLNavigation';
import CountUp from '../../../components/CountUp';
import { WarpResourcesPanel } from '../../../components/WarpResourcesPanel';

import { selectTotal, selectWarpTravel, enterWarp, exitWarp } from '../../../app/gameSlice';
import { playSound } from '../../../app/soundSlice';
import { useAppSelector, useAppDispatch } from '../../../app/hooks';
import { useDamageWave } from '../../../hooks/useDamageWave';
import { ST2_K2_RESOURCES, ST2_TOI_RESOURCES, ST2_TOTAL_RESOURCES, ST2_TRAPPIST_RESOURCES } from '../../../app/constants';

interface InterfaceProps {
    onEarthClick: (pos: { x: number; y: number }) => void;
}

export const Cosmos: React.FC<InterfaceProps> = ({ onEarthClick }) => {
    const [isEarthBouncing, setIsEarthBouncing] = useState(false);
    const [showWarpTooltip, setShowWarpTooltip] = useState(false);
    const total = useAppSelector(selectTotal);
    const game = useAppSelector(state => state.game);
    const warpTravel = useAppSelector(selectWarpTravel);
    const damageWave = useDamageWave();
    const dispatch = useAppDispatch();
    
    // Отслеживаем предыдущее состояние варпа для звуков
    const prevWarpActive = useRef(warpTravel?.isActive);
    
    // Воспроизводим звуки при входе/выходе из варпа
    useEffect(() => {
        if (warpTravel?.isActive && !prevWarpActive.current) {
            // Вход в варп
            dispatch(playSound({ key: 'warpEnter' }));
        } else if (!warpTravel?.isActive && prevWarpActive.current) {
            // Выход из варпа
            dispatch(playSound({ key: 'warpExit' }));
        }
        prevWarpActive.current = warpTravel?.isActive;
    }, [warpTravel?.isActive, dispatch]);
    
    const isFTLActive = game.cosmicCivilization.FTL && game.ftlSystem.isActive;

    const handleClick = (event: React.MouseEvent) => {
        const clickPos = {
            x: event.clientX,
            y: event.clientY
        };
        onEarthClick(clickPos);
        
        // Запускаем анимацию подпрыгивания
        setIsEarthBouncing(true);
        setTimeout(() => setIsEarthBouncing(false), 500);
    };
    
    // Определяем интенсивность тряски в зависимости от множителя урона
    const getShakeIntensity = () => {
        if (!damageWave.isActive || warpTravel?.isActive) return '';
        
        if (damageWave.multiplier >= 10) return styles.shakeIntense;
        if (damageWave.multiplier >= 6) return styles.shakeHeavy;
        if (damageWave.multiplier >= 3) return styles.shakeMedium;
        return styles.shakeLight;
    };

    // Обработчик варп-кнопки
    const handleWarpToggle = () => {
        if (!warpTravel?.isUnlocked || game.stage !== 2) return;
        
        if (warpTravel.isActive) {
            dispatch(exitWarp());
        } else {
            // Проверяем, можно ли войти в варп (нет активной волны урона и достаточно ресурсов)
            if (!damageWave.isActive && game.resources >= (warpTravel.warpPrice || 0)) {
                dispatch(enterWarp());
            }
        }
    };

    // Проверяем доступность варпа
    const isWarpOnCooldown = warpTravel?.warpCooldownEndTime ? Date.now() < warpTravel.warpCooldownEndTime : false;
    const hasEnoughResources = game.resources >= (warpTravel?.warpPrice || 0);
    const canEnterWarp = warpTravel?.isUnlocked && !damageWave.isActive && !warpTravel.isActive && !isWarpOnCooldown && hasEnoughResources;
    const canExitWarp = warpTravel?.isActive;

    // Рассчитываем прогресс кулдауна варп-ресурсов
    const warpCooldownProgress = warpTravel?.warpCooldownEndTime ? 
        Math.max(0, (warpTravel.warpCooldownEndTime - Date.now()) / 30000) : 0;
    
    return (
        <div className={classNames(
            styles.cosmos,
            getShakeIntensity(),
            { [styles.warpActive]: warpTravel?.isActive }
        )}>
            <div className={classNames(
                styles.background,
                { [styles.warpBackground]: warpTravel?.isActive }
            )}></div>
            
            {/* Варп-кнопка */}
            {warpTravel?.isUnlocked && (
                <div className={styles.warpControls}>
                    <button
                        className={classNames(
                            styles.warpButton,
                            { 
                                [styles.active]: warpTravel.isActive,
                                [styles.disabled]: !canEnterWarp && !canExitWarp
                            }
                        )}
                        onClick={handleWarpToggle}
                        onMouseEnter={() => setShowWarpTooltip(true)}
                        onMouseLeave={() => setShowWarpTooltip(false)}
                        disabled={!canEnterWarp && !canExitWarp}
                    >
                        🔥 {warpTravel.isActive ? 'Выйти из Варпа' : (isWarpOnCooldown ? `Кулдаун (${Math.ceil((warpTravel.warpCooldownEndTime - Date.now()) / 1000)}с)` : (!hasEnoughResources ? `Нужно ${Math.floor((warpTravel.warpPrice || 0) - game.resources).toLocaleString()}₿` : 'Войти в Варп'))}
                    </button>
                    
                    {showWarpTooltip && (
                        <div className={styles.warpTooltip}>
                            <div className={styles.tooltipTitle}>Варп-Путешествие</div>
                            <div className={styles.tooltipContent}>
                                • Ресурсы накапливаются в 8 раз быстрее<br/>
                                • Цена входа: {Math.floor(warpTravel.warpPrice || 0).toLocaleString()}₿<br/>
                                • Расход по формуле: k × √время<br/>
                                • Нельзя войти во время волны урона<br/>
                                • Варп-ресурсы доступны через 30с после выхода
                            </div>
                        </div>
                    )}
                </div>
            )}

            {/* Варп-ресурсы */}
            {warpTravel && (
                <WarpResourcesPanel 
                    warpTravel={warpTravel}
                    warpCooldownProgress={warpCooldownProgress}
                />
            )}


            
            {isFTLActive && (<>
                <FTLNavigation />
                </>
            )}
            <ShipManager progress={isFTLActive ? (100 * (game.ftlSystem.currentStage / 4)) : total/ST2_TOTAL_RESOURCES} />
            
            <div className={classNames(
                styles.planets,
                { [styles.warpPlanets]: warpTravel?.isActive }
            )}>
                <div 
                    className={classNames(
                        styles.planet, 
                        styles.earth, 
                        { 
                            [styles.bounce]: isEarthBouncing,
                            [styles.warpDisabled]: warpTravel?.isActive
                        }
                    )} 
                    onClick={warpTravel?.isActive ? undefined : handleClick}
                ></div>
                <div className={classNames(
                    styles.group, 
                    styles.trappist, 
                    { 
                        [styles.locked]: total > ST2_TRAPPIST_RESOURCES || game.ftlSystem.currentStage >= 1,
                        [styles.warpDisabled]: warpTravel?.isActive
                    }
                )}>
                    <div className={classNames(styles.planet, styles.trappistd)}>TRAPPIST-1 d 41</div>
                    <div className={classNames(styles.planet, styles.trappiste)}>TRAPPIST-1 e 41</div>
                    <div className={classNames(styles.planet, styles.trappistf)}>TRAPPIST-1 f 41</div>
                    <div className={classNames(styles.planet, styles.trappistg)}>TRAPPIST-1 g 41</div>
                </div>
                <div className={classNames(
                    styles.planet, 
                    styles.toi, 
                    { 
                        [styles.locked]: total > ST2_TOI_RESOURCES || game.ftlSystem.currentStage >= 2,
                        [styles.warpDisabled]: warpTravel?.isActive
                    }
                )}>TOI-700 d 101</div>
                <div className={classNames(
                    styles.planet, 
                    styles.k2, 
                    { 
                        [styles.locked]: total > ST2_K2_RESOURCES || game.ftlSystem.currentStage >= 3,
                        [styles.warpDisabled]: warpTravel?.isActive
                    }
                )}>K2-72 e 217</div>
                <div className={classNames(
                    styles.planet, 
                    styles.kepler,
                    { [styles.warpDisabled]: warpTravel?.isActive }
                )}>Kepler-1649 c 301</div>
            </div>
        </div>
    );
};
